const snapshot = [{"name":"blyp-betterstack","type":"skill-md","description":"Portable Blyp connector add-on skill for Better Stack using connectors.betterstack, auto or manual log delivery, and Better Stack error tracking through the Sentry SDK.","url":"/.well-known/agent-skills/blyp-betterstack/SKILL.md","digest":"sha256:2972fad53b9ecf10fcea1bfca51535257b8796728deac52087b8398ad4fcabad","content":{"text":"---\nname: blyp-betterstack\ndescription: Portable Blyp connector add-on skill for Better Stack using connectors.betterstack, auto or manual log delivery, and Better Stack error tracking through the Sentry SDK.\n---\n\n# Blyp Better Stack\n\n## What this skill is for\n\nUse this add-on when Blyp logs or handled errors should be forwarded into Better Stack.\n\n## When to use it\n\n- Configuring `connectors.betterstack`\n- Choosing `mode: \"auto\"` or `mode: \"manual\"` for server log forwarding\n- Enabling Better Stack error tracking\n- Supporting browser or Expo requests that ask Blyp to forward into Better Stack\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure Better Stack on the server in `connectors.betterstack`.\n- Supported log delivery modes are `auto` and `manual`.\n- `ingestingHost` must be an absolute `http://` or `https://` URL.\n- Better Stack error tracking is configured under `connectors.betterstack.errorTracking`.\n- Blyp uses the Sentry SDK for Better Stack error tracking and reuses an existing Sentry client if one is already initialized.\n- Browser and Expo Better Stack requests still send to Blyp ingestion first.\n- Client `error` and `critical` logs are promoted to Better Stack exceptions when server-side Better Stack error tracking is configured.\n\n## Required implementation steps\n\n1. Add or update `connectors.betterstack` in `blyp.config.*`.\n2. Set `enabled: true` and choose `mode: \"auto\"` or `mode: \"manual\"` for log forwarding.\n3. Provide `sourceToken`, `ingestingHost`, and optional `serviceName`.\n4. If the application wants Blyp-managed handled error capture, configure `errorTracking.dsn` and related options.\n5. If manual control is required, use `@blyp/core/betterstack` APIs instead of assuming auto delivery.\n6. If browser or Expo code requests `connector: \"betterstack\"`, verify the server connector is configured first.\n\n## Verification checklist\n\n- `connectors.betterstack` exists in `blyp.config.*`\n- The connector mode is explicit\n- `ingestingHost` is a valid absolute URL\n- Better Stack error tracking is configured intentionally when needed\n- Existing app-level Sentry initialization is not accidentally replaced\n- Browser or Expo Better Stack forwarding still targets Blyp ingestion first\n- Manual code imports from `@blyp/core/betterstack` when auto mode is not desired\n\n## References\n\n- Config key: `connectors.betterstack`\n- Manual import path: `@blyp/core/betterstack`\n- Manual APIs: `createBetterStackLogger()`, `createStructuredBetterStackLogger()`, `createBetterStackErrorTracker()`, `captureBetterStackException()`\n"},"sha256":"2972fad53b9ecf10fcea1bfca51535257b8796728deac52087b8398ad4fcabad","skillDocument":"---\nname: blyp-betterstack\ndescription: Portable Blyp connector add-on skill for Better Stack using connectors.betterstack, auto or manual log delivery, and Better Stack error tracking through the Sentry SDK.\n---\n\n# Blyp Better Stack\n\n## What this skill is for\n\nUse this add-on when Blyp logs or handled errors should be forwarded into Better Stack.\n\n## When to use it\n\n- Configuring `connectors.betterstack`\n- Choosing `mode: \"auto\"` or `mode: \"manual\"` for server log forwarding\n- Enabling Better Stack error tracking\n- Supporting browser or Expo requests that ask Blyp to forward into Better Stack\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure Better Stack on the server in `connectors.betterstack`.\n- Supported log delivery modes are `auto` and `manual`.\n- `ingestingHost` must be an absolute `http://` or `https://` URL.\n- Better Stack error tracking is configured under `connectors.betterstack.errorTracking`.\n- Blyp uses the Sentry SDK for Better Stack error tracking and reuses an existing Sentry client if one is already initialized.\n- Browser and Expo Better Stack requests still send to Blyp ingestion first.\n- Client `error` and `critical` logs are promoted to Better Stack exceptions when server-side Better Stack error tracking is configured.\n\n## Required implementation steps\n\n1. Add or update `connectors.betterstack` in `blyp.config.*`.\n2. Set `enabled: true` and choose `mode: \"auto\"` or `mode: \"manual\"` for log forwarding.\n3. Provide `sourceToken`, `ingestingHost`, and optional `serviceName`.\n4. If the application wants Blyp-managed handled error capture, configure `errorTracking.dsn` and related options.\n5. If manual control is required, use `@blyp/core/betterstack` APIs instead of assuming auto delivery.\n6. If browser or Expo code requests `connector: \"betterstack\"`, verify the server connector is configured first.\n\n## Verification checklist\n\n- `connectors.betterstack` exists in `blyp.config.*`\n- The connector mode is explicit\n- `ingestingHost` is a valid absolute URL\n- Better Stack error tracking is configured intentionally when needed\n- Existing app-level Sentry initialization is not accidentally replaced\n- Browser or Expo Better Stack forwarding still targets Blyp ingestion first\n- Manual code imports from `@blyp/core/betterstack` when auto mode is not desired\n\n## References\n\n- Config key: `connectors.betterstack`\n- Manual import path: `@blyp/core/betterstack`\n- Manual APIs: `createBetterStackLogger()`, `createStructuredBetterStackLogger()`, `createBetterStackErrorTracker()`, `captureBetterStackException()`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-betterstack/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-betterstack\ndescription: Portable Blyp connector add-on skill for Better Stack using connectors.betterstack, auto or manual log delivery, and Better Stack error tracking through the Sentry SDK.\n---\n\n# Blyp Better Stack\n\n## What this skill is for\n\nUse this add-on when Blyp logs or handled errors should be forwarded into Better Stack.\n\n## When to use it\n\n- Configuring `connectors.betterstack`\n- Choosing `mode: \"auto\"` or `mode: \"manual\"` for server log forwarding\n- Enabling Better Stack error tracking\n- Supporting browser or Expo requests that ask Blyp to forward into Better Stack\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure Better Stack on the server in `connectors.betterstack`.\n- Supported log delivery modes are `auto` and `manual`.\n- `ingestingHost` must be an absolute `http://` or `https://` URL.\n- Better Stack error tracking is configured under `connectors.betterstack.errorTracking`.\n- Blyp uses the Sentry SDK for Better Stack error tracking and reuses an existing Sentry client if one is already initialized.\n- Browser and Expo Better Stack requests still send to Blyp ingestion first.\n- Client `error` and `critical` logs are promoted to Better Stack exceptions when server-side Better Stack error tracking is configured.\n\n## Required implementation steps\n\n1. Add or update `connectors.betterstack` in `blyp.config.*`.\n2. Set `enabled: true` and choose `mode: \"auto\"` or `mode: \"manual\"` for log forwarding.\n3. Provide `sourceToken`, `ingestingHost`, and optional `serviceName`.\n4. If the application wants Blyp-managed handled error capture, configure `errorTracking.dsn` and related options.\n5. If manual control is required, use `@blyp/core/betterstack` APIs instead of assuming auto delivery.\n6. If browser or Expo code requests `connector: \"betterstack\"`, verify the server connector is configured first.\n\n## Verification checklist\n\n- `connectors.betterstack` exists in `blyp.config.*`\n- The connector mode is explicit\n- `ingestingHost` is a valid absolute URL\n- Better Stack error tracking is configured intentionally when needed\n- Existing app-level Sentry initialization is not accidentally replaced\n- Browser or Expo Better Stack forwarding still targets Blyp ingestion first\n- Manual code imports from `@blyp/core/betterstack` when auto mode is not desired\n\n## References\n\n- Config key: `connectors.betterstack`\n- Manual import path: `@blyp/core/betterstack`\n- Manual APIs: `createBetterStackLogger()`, `createStructuredBetterStackLogger()`, `createBetterStackErrorTracker()`, `captureBetterStackException()`\n"},"sha256":"2972fad53b9ecf10fcea1bfca51535257b8796728deac52087b8398ad4fcabad","digest":"sha256:2972fad53b9ecf10fcea1bfca51535257b8796728deac52087b8398ad4fcabad"}]},{"name":"blyp-client-expo","type":"skill-md","description":"Portable Blyp add-on skill for browser and Expo logging with @blyp/core/client, @blyp/core/expo, default /inngest ingestion, retry queues, and connector forwarding requests through Blyp.","url":"/.well-known/agent-skills/blyp-client-expo/SKILL.md","digest":"sha256:bc778980e8873a260045c9ef959cd771c492785b8dfe1d310bf625ada133f6a0","content":{"text":"---\nname: blyp-client-expo\ndescription: Portable Blyp add-on skill for browser and Expo logging with @blyp/core/client, @blyp/core/expo, default /inngest ingestion, retry queues, and connector forwarding requests through Blyp.\ncompatibility: Requires a browser or Expo project; Expo projects also require expo-network.\n---\n\n# Blyp Client and Expo\n\n## What this skill is for\n\nUse this add-on when Blyp should emit logs from browsers or Expo apps into a Blyp-enabled backend.\n\n## When to use it\n\n- Adding `createClientLogger()` in a browser app\n- Adding `createExpoLogger()` in an Expo app\n- Enabling remote sync to Blyp ingestion\n- Requesting PostHog, Sentry, Databuddy, or OTLP forwarding from the client side\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Browser apps import from `@blyp/core/client`.\n- Expo apps import from `@blyp/core/expo`.\n- Browser ingestion defaults to `/inngest`.\n- Browser delivery retries retryable failures with an in-memory queue.\n- Expo requires an absolute `http://` or `https://` ingestion endpoint.\n- Expo requires `expo-network` for connectivity-aware retry behavior.\n- Browser and Expo connector requests still go through Blyp ingestion first.\n\n## Required implementation steps\n\n1. Pick the correct runtime import:\n   - Browser: `createClientLogger` from `@blyp/core/client`\n   - Expo: `createExpoLogger` from `@blyp/core/expo`\n2. Keep the endpoint aligned with the server ingestion route:\n   - Browser default: `/inngest`\n   - Expo: absolute backend URL such as `https://api.example.com/inngest`\n3. Configure delivery options only when the repo needs custom retry behavior.\n4. If connector forwarding is requested, set `connector` on the client logger and verify the server connector exists.\n5. For Expo, ensure `expo-network` is installed before relying on remote sync.\n\n## Verification checklist\n\n- Browser code imports `@blyp/core/client`\n- Expo code imports `@blyp/core/expo`\n- Browser endpoint defaults to or matches `/inngest`\n- Expo endpoint is absolute\n- `expo-network` is installed when Expo remote sync is enabled\n- Any connector request is backed by a server-side Blyp connector\n\n## References\n\n- Browser import path: `@blyp/core/client`\n- Expo import path: `@blyp/core/expo`\n- Main APIs: `createClientLogger()`, `createExpoLogger()`\n- Connector request shapes: `\"posthog\"`, `\"sentry\"`, `\"databuddy\"`, `{ type: \"otlp\", name: \"<target>\" }`\n"},"sha256":"bc778980e8873a260045c9ef959cd771c492785b8dfe1d310bf625ada133f6a0","skillDocument":"---\nname: blyp-client-expo\ndescription: Portable Blyp add-on skill for browser and Expo logging with @blyp/core/client, @blyp/core/expo, default /inngest ingestion, retry queues, and connector forwarding requests through Blyp.\ncompatibility: Requires a browser or Expo project; Expo projects also require expo-network.\n---\n\n# Blyp Client and Expo\n\n## What this skill is for\n\nUse this add-on when Blyp should emit logs from browsers or Expo apps into a Blyp-enabled backend.\n\n## When to use it\n\n- Adding `createClientLogger()` in a browser app\n- Adding `createExpoLogger()` in an Expo app\n- Enabling remote sync to Blyp ingestion\n- Requesting PostHog, Sentry, Databuddy, or OTLP forwarding from the client side\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Browser apps import from `@blyp/core/client`.\n- Expo apps import from `@blyp/core/expo`.\n- Browser ingestion defaults to `/inngest`.\n- Browser delivery retries retryable failures with an in-memory queue.\n- Expo requires an absolute `http://` or `https://` ingestion endpoint.\n- Expo requires `expo-network` for connectivity-aware retry behavior.\n- Browser and Expo connector requests still go through Blyp ingestion first.\n\n## Required implementation steps\n\n1. Pick the correct runtime import:\n   - Browser: `createClientLogger` from `@blyp/core/client`\n   - Expo: `createExpoLogger` from `@blyp/core/expo`\n2. Keep the endpoint aligned with the server ingestion route:\n   - Browser default: `/inngest`\n   - Expo: absolute backend URL such as `https://api.example.com/inngest`\n3. Configure delivery options only when the repo needs custom retry behavior.\n4. If connector forwarding is requested, set `connector` on the client logger and verify the server connector exists.\n5. For Expo, ensure `expo-network` is installed before relying on remote sync.\n\n## Verification checklist\n\n- Browser code imports `@blyp/core/client`\n- Expo code imports `@blyp/core/expo`\n- Browser endpoint defaults to or matches `/inngest`\n- Expo endpoint is absolute\n- `expo-network` is installed when Expo remote sync is enabled\n- Any connector request is backed by a server-side Blyp connector\n\n## References\n\n- Browser import path: `@blyp/core/client`\n- Expo import path: `@blyp/core/expo`\n- Main APIs: `createClientLogger()`, `createExpoLogger()`\n- Connector request shapes: `\"posthog\"`, `\"sentry\"`, `\"databuddy\"`, `{ type: \"otlp\", name: \"<target>\" }`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-client-expo/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-client-expo\ndescription: Portable Blyp add-on skill for browser and Expo logging with @blyp/core/client, @blyp/core/expo, default /inngest ingestion, retry queues, and connector forwarding requests through Blyp.\ncompatibility: Requires a browser or Expo project; Expo projects also require expo-network.\n---\n\n# Blyp Client and Expo\n\n## What this skill is for\n\nUse this add-on when Blyp should emit logs from browsers or Expo apps into a Blyp-enabled backend.\n\n## When to use it\n\n- Adding `createClientLogger()` in a browser app\n- Adding `createExpoLogger()` in an Expo app\n- Enabling remote sync to Blyp ingestion\n- Requesting PostHog, Sentry, Databuddy, or OTLP forwarding from the client side\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Browser apps import from `@blyp/core/client`.\n- Expo apps import from `@blyp/core/expo`.\n- Browser ingestion defaults to `/inngest`.\n- Browser delivery retries retryable failures with an in-memory queue.\n- Expo requires an absolute `http://` or `https://` ingestion endpoint.\n- Expo requires `expo-network` for connectivity-aware retry behavior.\n- Browser and Expo connector requests still go through Blyp ingestion first.\n\n## Required implementation steps\n\n1. Pick the correct runtime import:\n   - Browser: `createClientLogger` from `@blyp/core/client`\n   - Expo: `createExpoLogger` from `@blyp/core/expo`\n2. Keep the endpoint aligned with the server ingestion route:\n   - Browser default: `/inngest`\n   - Expo: absolute backend URL such as `https://api.example.com/inngest`\n3. Configure delivery options only when the repo needs custom retry behavior.\n4. If connector forwarding is requested, set `connector` on the client logger and verify the server connector exists.\n5. For Expo, ensure `expo-network` is installed before relying on remote sync.\n\n## Verification checklist\n\n- Browser code imports `@blyp/core/client`\n- Expo code imports `@blyp/core/expo`\n- Browser endpoint defaults to or matches `/inngest`\n- Expo endpoint is absolute\n- `expo-network` is installed when Expo remote sync is enabled\n- Any connector request is backed by a server-side Blyp connector\n\n## References\n\n- Browser import path: `@blyp/core/client`\n- Expo import path: `@blyp/core/expo`\n- Main APIs: `createClientLogger()`, `createExpoLogger()`\n- Connector request shapes: `\"posthog\"`, `\"sentry\"`, `\"databuddy\"`, `{ type: \"otlp\", name: \"<target>\" }`\n"},"sha256":"bc778980e8873a260045c9ef959cd771c492785b8dfe1d310bf625ada133f6a0","digest":"sha256:bc778980e8873a260045c9ef959cd771c492785b8dfe1d310bf625ada133f6a0"}]},{"name":"blyp-convex","type":"skill-md","description":"Portable Blyp add-on skill for Convex isolate logging with @blyp/core/convex, shared blyp.config.ts via @blyp/core/config, handler wrap(), and action-only HTTP export for PostHog, Axiom, Better Stack, Sentry, Databuddy, HTTP, and OTLP.","url":"/.well-known/agent-skills/blyp-convex/SKILL.md","digest":"sha256:5fa4cda0ee53091486cc27d576b9536ae45dff0f005a9125149283cb60262102","content":{"text":"---\nname: blyp-convex\ndescription: Portable Blyp add-on skill for Convex isolate logging with @blyp/core/convex, shared blyp.config.ts via @blyp/core/config, handler wrap(), and action-only HTTP export for PostHog, Axiom, Better Stack, Sentry, Databuddy, HTTP, and OTLP.\ncompatibility: Requires a Convex project; remote connector export runs from Convex actions.\n---\n\n# Blyp Convex\n\n## What this skill is for\n\nUse this add-on when the runtime is Convex rather than Node.js or Bun server adapters.\n\n## When to use it\n\n- Logging from Convex queries, mutations, or actions\n- Sharing one `blyp.config.ts` with an HTTP API in a monorepo\n- Exporting action logs to PostHog, Axiom, Better Stack, Sentry, Databuddy, HTTP webhooks, Grafana, or another OTLP HTTP logs endpoint\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first, but override its Node/Bun assumptions with Convex rules.\n- Import from `@blyp/core/convex`. Never import the root `@blyp/core` logger inside Convex functions.\n- If Convex imports `blyp.config.ts`, that file must use `defineConfig` from `@blyp/core/config`, not `@blyp/core`.\n- Pass the shared config object into `configureConvexLogger(blypConfig)`. Convex does not walk the filesystem.\n- Use the default `logger`. Call `configureConvexLogger()` once in a shared Convex module.\n- Use `createConvexLogger()` only for a second instance.\n- Keep importing `mutation`, `query`, and `action` from `convex/server`. Do not look for Blyp re-exports of those builders.\n- Convex uses `level`, `redact`, and isolate-safe HTTP export for `posthog`, `axiom`, `betterstack`, `sentry`, `databuddy`, `http`, and auto `connectors.otlp`.\n- Shared `connectors.posthog`, `connectors.betterstack`, `connectors.sentry`, `connectors.databuddy`, and `connectors.http` map to the same action-only `fetch` sinks. Do not duplicate them as raw `connectors.otlp` unless you need a collector that is not one of those vendors.\n- File logging, database destinations, delivery queues, client ingestion, and vendor exception SDKs are ignored. Blyp warns once for each.\n- Without a usable remote sink, Convex writes `console.*` only and warns once.\n- Convex-only config can be `configureConvexLogger({ posthog, axiom, betterstack, sentry, databuddy, http, otlp })`.\n- `otlp: false` disables every remote export. `posthog: false` (and the other vendor `false` flags) skip that vendor.\n- Queries and mutations can only write `console.*`. They cannot `fetch`.\n- Actions and HTTP actions can export over JSON HTTP `fetch` when a sink is configured.\n- Wrap the handler, not Convex's `action` helper: `handler: logger.wrap(async (ctx, args) => { ... })`.\n- `wrap` binds `ctx` and flushes remote export for actions, including when the handler throws.\n- If you skip `wrap` on an action, call `logger.bind(ctx)` and `await logger.flush()` yourself.\n\n## Required implementation steps\n\n1. If the repo shares `blyp.config.ts` with Convex, import `defineConfig` from `@blyp/core/config`.\n2. Configure PostHog, Better Stack, Sentry, Databuddy, HTTP, and OTLP under `connectors.*`, or pass `posthog` / `axiom` / `betterstack` / `sentry` / `databuddy` / `http` / `otlp` to `configureConvexLogger()`.\n3. Import that config into `convex/logger.ts` and call `configureConvexLogger(blypConfig)`.\n4. Import `logger` from that Convex module, not `@blyp/core`.\n5. For actions, wrap the handler with `logger.wrap(...)` so `ctx` is bound and remote export flushes.\n6. Leave file, database, delivery queues, and exception autocapture to the HTTP API. Expect Convex warnings for those Node-only sinks.\n\n## Verification checklist\n\n- Convex functions import from `@blyp/core/convex`\n- Shared `blyp.config.ts` imports `defineConfig` from `@blyp/core/config` when Convex loads it\n- `configureConvexLogger()` receives that config object\n- A vendor object or auto connector exists if action logs should leave Convex\n- Convex builders still come from `convex/server`\n- Action handlers use `logger.wrap(...)` or manual `bind` plus `flush`\n- Queries and mutations are not expected to export remotely\n\n## References\n\n- Import path: `@blyp/core/convex`\n- Shared config: `@blyp/core/config`\n- Main APIs: `logger`, `configureConvexLogger()`, `createConvexLogger()`, `defineConfig()`\n- Handler binding: `logger.wrap()`, `logger.bind()`, `logger.flush()`\n"},"sha256":"5fa4cda0ee53091486cc27d576b9536ae45dff0f005a9125149283cb60262102","skillDocument":"---\nname: blyp-convex\ndescription: Portable Blyp add-on skill for Convex isolate logging with @blyp/core/convex, shared blyp.config.ts via @blyp/core/config, handler wrap(), and action-only HTTP export for PostHog, Axiom, Better Stack, Sentry, Databuddy, HTTP, and OTLP.\ncompatibility: Requires a Convex project; remote connector export runs from Convex actions.\n---\n\n# Blyp Convex\n\n## What this skill is for\n\nUse this add-on when the runtime is Convex rather than Node.js or Bun server adapters.\n\n## When to use it\n\n- Logging from Convex queries, mutations, or actions\n- Sharing one `blyp.config.ts` with an HTTP API in a monorepo\n- Exporting action logs to PostHog, Axiom, Better Stack, Sentry, Databuddy, HTTP webhooks, Grafana, or another OTLP HTTP logs endpoint\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first, but override its Node/Bun assumptions with Convex rules.\n- Import from `@blyp/core/convex`. Never import the root `@blyp/core` logger inside Convex functions.\n- If Convex imports `blyp.config.ts`, that file must use `defineConfig` from `@blyp/core/config`, not `@blyp/core`.\n- Pass the shared config object into `configureConvexLogger(blypConfig)`. Convex does not walk the filesystem.\n- Use the default `logger`. Call `configureConvexLogger()` once in a shared Convex module.\n- Use `createConvexLogger()` only for a second instance.\n- Keep importing `mutation`, `query`, and `action` from `convex/server`. Do not look for Blyp re-exports of those builders.\n- Convex uses `level`, `redact`, and isolate-safe HTTP export for `posthog`, `axiom`, `betterstack`, `sentry`, `databuddy`, `http`, and auto `connectors.otlp`.\n- Shared `connectors.posthog`, `connectors.betterstack`, `connectors.sentry`, `connectors.databuddy`, and `connectors.http` map to the same action-only `fetch` sinks. Do not duplicate them as raw `connectors.otlp` unless you need a collector that is not one of those vendors.\n- File logging, database destinations, delivery queues, client ingestion, and vendor exception SDKs are ignored. Blyp warns once for each.\n- Without a usable remote sink, Convex writes `console.*` only and warns once.\n- Convex-only config can be `configureConvexLogger({ posthog, axiom, betterstack, sentry, databuddy, http, otlp })`.\n- `otlp: false` disables every remote export. `posthog: false` (and the other vendor `false` flags) skip that vendor.\n- Queries and mutations can only write `console.*`. They cannot `fetch`.\n- Actions and HTTP actions can export over JSON HTTP `fetch` when a sink is configured.\n- Wrap the handler, not Convex's `action` helper: `handler: logger.wrap(async (ctx, args) => { ... })`.\n- `wrap` binds `ctx` and flushes remote export for actions, including when the handler throws.\n- If you skip `wrap` on an action, call `logger.bind(ctx)` and `await logger.flush()` yourself.\n\n## Required implementation steps\n\n1. If the repo shares `blyp.config.ts` with Convex, import `defineConfig` from `@blyp/core/config`.\n2. Configure PostHog, Better Stack, Sentry, Databuddy, HTTP, and OTLP under `connectors.*`, or pass `posthog` / `axiom` / `betterstack` / `sentry` / `databuddy` / `http` / `otlp` to `configureConvexLogger()`.\n3. Import that config into `convex/logger.ts` and call `configureConvexLogger(blypConfig)`.\n4. Import `logger` from that Convex module, not `@blyp/core`.\n5. For actions, wrap the handler with `logger.wrap(...)` so `ctx` is bound and remote export flushes.\n6. Leave file, database, delivery queues, and exception autocapture to the HTTP API. Expect Convex warnings for those Node-only sinks.\n\n## Verification checklist\n\n- Convex functions import from `@blyp/core/convex`\n- Shared `blyp.config.ts` imports `defineConfig` from `@blyp/core/config` when Convex loads it\n- `configureConvexLogger()` receives that config object\n- A vendor object or auto connector exists if action logs should leave Convex\n- Convex builders still come from `convex/server`\n- Action handlers use `logger.wrap(...)` or manual `bind` plus `flush`\n- Queries and mutations are not expected to export remotely\n\n## References\n\n- Import path: `@blyp/core/convex`\n- Shared config: `@blyp/core/config`\n- Main APIs: `logger`, `configureConvexLogger()`, `createConvexLogger()`, `defineConfig()`\n- Handler binding: `logger.wrap()`, `logger.bind()`, `logger.flush()`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-convex/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-convex\ndescription: Portable Blyp add-on skill for Convex isolate logging with @blyp/core/convex, shared blyp.config.ts via @blyp/core/config, handler wrap(), and action-only HTTP export for PostHog, Axiom, Better Stack, Sentry, Databuddy, HTTP, and OTLP.\ncompatibility: Requires a Convex project; remote connector export runs from Convex actions.\n---\n\n# Blyp Convex\n\n## What this skill is for\n\nUse this add-on when the runtime is Convex rather than Node.js or Bun server adapters.\n\n## When to use it\n\n- Logging from Convex queries, mutations, or actions\n- Sharing one `blyp.config.ts` with an HTTP API in a monorepo\n- Exporting action logs to PostHog, Axiom, Better Stack, Sentry, Databuddy, HTTP webhooks, Grafana, or another OTLP HTTP logs endpoint\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first, but override its Node/Bun assumptions with Convex rules.\n- Import from `@blyp/core/convex`. Never import the root `@blyp/core` logger inside Convex functions.\n- If Convex imports `blyp.config.ts`, that file must use `defineConfig` from `@blyp/core/config`, not `@blyp/core`.\n- Pass the shared config object into `configureConvexLogger(blypConfig)`. Convex does not walk the filesystem.\n- Use the default `logger`. Call `configureConvexLogger()` once in a shared Convex module.\n- Use `createConvexLogger()` only for a second instance.\n- Keep importing `mutation`, `query`, and `action` from `convex/server`. Do not look for Blyp re-exports of those builders.\n- Convex uses `level`, `redact`, and isolate-safe HTTP export for `posthog`, `axiom`, `betterstack`, `sentry`, `databuddy`, `http`, and auto `connectors.otlp`.\n- Shared `connectors.posthog`, `connectors.betterstack`, `connectors.sentry`, `connectors.databuddy`, and `connectors.http` map to the same action-only `fetch` sinks. Do not duplicate them as raw `connectors.otlp` unless you need a collector that is not one of those vendors.\n- File logging, database destinations, delivery queues, client ingestion, and vendor exception SDKs are ignored. Blyp warns once for each.\n- Without a usable remote sink, Convex writes `console.*` only and warns once.\n- Convex-only config can be `configureConvexLogger({ posthog, axiom, betterstack, sentry, databuddy, http, otlp })`.\n- `otlp: false` disables every remote export. `posthog: false` (and the other vendor `false` flags) skip that vendor.\n- Queries and mutations can only write `console.*`. They cannot `fetch`.\n- Actions and HTTP actions can export over JSON HTTP `fetch` when a sink is configured.\n- Wrap the handler, not Convex's `action` helper: `handler: logger.wrap(async (ctx, args) => { ... })`.\n- `wrap` binds `ctx` and flushes remote export for actions, including when the handler throws.\n- If you skip `wrap` on an action, call `logger.bind(ctx)` and `await logger.flush()` yourself.\n\n## Required implementation steps\n\n1. If the repo shares `blyp.config.ts` with Convex, import `defineConfig` from `@blyp/core/config`.\n2. Configure PostHog, Better Stack, Sentry, Databuddy, HTTP, and OTLP under `connectors.*`, or pass `posthog` / `axiom` / `betterstack` / `sentry` / `databuddy` / `http` / `otlp` to `configureConvexLogger()`.\n3. Import that config into `convex/logger.ts` and call `configureConvexLogger(blypConfig)`.\n4. Import `logger` from that Convex module, not `@blyp/core`.\n5. For actions, wrap the handler with `logger.wrap(...)` so `ctx` is bound and remote export flushes.\n6. Leave file, database, delivery queues, and exception autocapture to the HTTP API. Expect Convex warnings for those Node-only sinks.\n\n## Verification checklist\n\n- Convex functions import from `@blyp/core/convex`\n- Shared `blyp.config.ts` imports `defineConfig` from `@blyp/core/config` when Convex loads it\n- `configureConvexLogger()` receives that config object\n- A vendor object or auto connector exists if action logs should leave Convex\n- Convex builders still come from `convex/server`\n- Action handlers use `logger.wrap(...)` or manual `bind` plus `flush`\n- Queries and mutations are not expected to export remotely\n\n## References\n\n- Import path: `@blyp/core/convex`\n- Shared config: `@blyp/core/config`\n- Main APIs: `logger`, `configureConvexLogger()`, `createConvexLogger()`, `defineConfig()`\n- Handler binding: `logger.wrap()`, `logger.bind()`, `logger.flush()`\n"},"sha256":"5fa4cda0ee53091486cc27d576b9536ae45dff0f005a9125149283cb60262102","digest":"sha256:5fa4cda0ee53091486cc27d576b9536ae45dff0f005a9125149283cb60262102"}]},{"name":"blyp-core","type":"skill-md","description":"Portable Blyp integration skill for installing @blyp/core, choosing the right runtime export, configuring blyp.config.*, wiring /inngest ingestion, and keeping server, browser, and Expo logging production-safe.","url":"/.well-known/agent-skills/blyp-core/SKILL.md","digest":"sha256:0a34e9ef5b2248d2889d9e5c343ff284c2ff1f2f2b1abc3f45d47330ff39c3c3","content":{"text":"---\nname: blyp-core\ndescription: Portable Blyp integration skill for installing @blyp/core, choosing the right runtime export, configuring blyp.config.*, wiring /inngest ingestion, and keeping server, browser, and Expo logging production-safe.\ncompatibility: Requires a JavaScript or TypeScript project using Bun, pnpm, npm, or Yarn.\n---\n\n# Blyp Core\n\n## What this skill is for\n\nUse this skill whenever an agent needs to add, review, or change Blyp logging in an application. This is the baseline skill for all Blyp work.\n\n## When to use it\n\n- Installing `@blyp/core` in a new project\n- Choosing the correct Blyp import path for the runtime\n- Adding or updating `blyp.config.*`\n- Enabling browser or Expo log ingestion\n- Preparing the project for Blyp connector add-ons or framework add-ons\n\n## Blyp-specific rules and constraints\n\n- The npm package name is `@blyp/core`.\n- Always choose the subpath that matches the runtime instead of forcing the root package everywhere.\n- Prefer shared project config in `blyp.config.ts`, `blyp.config.mts`, `blyp.config.cts`, `blyp.config.js`, `blyp.config.mjs`, `blyp.config.cjs`, or `blyp.config.json`.\n- Default client ingestion path is `/inngest`.\n- Browser and Expo connector delivery still posts to Blyp ingestion first. They do not send directly to PostHog, Sentry, Databuddy, or OTLP vendors.\n- Prefer production-safe defaults over the shortest demo snippet.\n- When client logging is enabled, verify that the mounted handler path matches the configured ingestion path exactly.\n- Treat unsupported presets as out of scope unless another Blyp skill explicitly covers them.\n\n## Required implementation steps\n\n1. Install `@blyp/core` with the package manager already used by the repo.\n2. Identify the runtime and select the matching Blyp entry:\n   - `@blyp/core` for root logger, standalone logger, config helpers, structured logs, and errors\n   - `@blyp/core/client` for browser logging\n   - `@blyp/core/expo` for Expo apps\n   - `@blyp/core/config` for isolate-safe `defineConfig()` when Convex or Workers will import `blyp.config.ts`\n   - `@blyp/core/<framework>` for framework adapters such as `nextjs`, `react-router`, `nuxt`, `express`, `hono`, `elysia`, `workers`, or `convex`\n3. Add or update `blyp.config.*` if the project needs shared log level, file logging, client ingestion, or connector configuration.\n4. If browser logging is enabled, keep the ingestion path aligned across config and server route mounting. Default to `/inngest` unless the repo already standardizes a different path.\n5. If connectors are involved, configure them on the server side first. Client and Expo requests depend on server connector configuration.\n6. Reuse existing Blyp helpers where possible:\n   - `logger`\n   - `createStandaloneLogger`\n   - `createStructuredLog`\n   - `createError`\n   - `parseError`\n7. Add a framework or connector add-on skill when runtime-specific behavior matters.\n\n## Verification checklist\n\n- `@blyp/core` is installed and imported from the correct subpath\n- Any shared Blyp settings live in a supported `blyp.config.*` file\n- Client ingestion uses the expected path, defaulting to `/inngest`\n- Browser or Expo connector requests are backed by server connector configuration\n- No framework-specific wiring is guessed when an adapter-specific Blyp skill exists\n- The final implementation favors safe config and correct handler mounting over the smallest possible snippet\n\n## References\n\n- Package: `@blyp/core`\n- Config files: `blyp.config.ts`, `blyp.config.mts`, `blyp.config.cts`, `blyp.config.js`, `blyp.config.mjs`, `blyp.config.cjs`, `blyp.config.json`\n- Core imports: `logger`, `createStandaloneLogger`, `createStructuredLog`, `createError`, `parseError`\n- Related add-ons: `blyp-nextjs`, `blyp-react-router`, `blyp-nuxt`, `blyp-express`, `blyp-hono`, `blyp-elysia`, `blyp-workers`, `blyp-convex`, `blyp-client-expo`, `blyp-betterstack`, `blyp-databuddy`, `blyp-posthog`, `blyp-sentry`, `blyp-otlp`\n"},"sha256":"0a34e9ef5b2248d2889d9e5c343ff284c2ff1f2f2b1abc3f45d47330ff39c3c3","skillDocument":"---\nname: blyp-core\ndescription: Portable Blyp integration skill for installing @blyp/core, choosing the right runtime export, configuring blyp.config.*, wiring /inngest ingestion, and keeping server, browser, and Expo logging production-safe.\ncompatibility: Requires a JavaScript or TypeScript project using Bun, pnpm, npm, or Yarn.\n---\n\n# Blyp Core\n\n## What this skill is for\n\nUse this skill whenever an agent needs to add, review, or change Blyp logging in an application. This is the baseline skill for all Blyp work.\n\n## When to use it\n\n- Installing `@blyp/core` in a new project\n- Choosing the correct Blyp import path for the runtime\n- Adding or updating `blyp.config.*`\n- Enabling browser or Expo log ingestion\n- Preparing the project for Blyp connector add-ons or framework add-ons\n\n## Blyp-specific rules and constraints\n\n- The npm package name is `@blyp/core`.\n- Always choose the subpath that matches the runtime instead of forcing the root package everywhere.\n- Prefer shared project config in `blyp.config.ts`, `blyp.config.mts`, `blyp.config.cts`, `blyp.config.js`, `blyp.config.mjs`, `blyp.config.cjs`, or `blyp.config.json`.\n- Default client ingestion path is `/inngest`.\n- Browser and Expo connector delivery still posts to Blyp ingestion first. They do not send directly to PostHog, Sentry, Databuddy, or OTLP vendors.\n- Prefer production-safe defaults over the shortest demo snippet.\n- When client logging is enabled, verify that the mounted handler path matches the configured ingestion path exactly.\n- Treat unsupported presets as out of scope unless another Blyp skill explicitly covers them.\n\n## Required implementation steps\n\n1. Install `@blyp/core` with the package manager already used by the repo.\n2. Identify the runtime and select the matching Blyp entry:\n   - `@blyp/core` for root logger, standalone logger, config helpers, structured logs, and errors\n   - `@blyp/core/client` for browser logging\n   - `@blyp/core/expo` for Expo apps\n   - `@blyp/core/config` for isolate-safe `defineConfig()` when Convex or Workers will import `blyp.config.ts`\n   - `@blyp/core/<framework>` for framework adapters such as `nextjs`, `react-router`, `nuxt`, `express`, `hono`, `elysia`, `workers`, or `convex`\n3. Add or update `blyp.config.*` if the project needs shared log level, file logging, client ingestion, or connector configuration.\n4. If browser logging is enabled, keep the ingestion path aligned across config and server route mounting. Default to `/inngest` unless the repo already standardizes a different path.\n5. If connectors are involved, configure them on the server side first. Client and Expo requests depend on server connector configuration.\n6. Reuse existing Blyp helpers where possible:\n   - `logger`\n   - `createStandaloneLogger`\n   - `createStructuredLog`\n   - `createError`\n   - `parseError`\n7. Add a framework or connector add-on skill when runtime-specific behavior matters.\n\n## Verification checklist\n\n- `@blyp/core` is installed and imported from the correct subpath\n- Any shared Blyp settings live in a supported `blyp.config.*` file\n- Client ingestion uses the expected path, defaulting to `/inngest`\n- Browser or Expo connector requests are backed by server connector configuration\n- No framework-specific wiring is guessed when an adapter-specific Blyp skill exists\n- The final implementation favors safe config and correct handler mounting over the smallest possible snippet\n\n## References\n\n- Package: `@blyp/core`\n- Config files: `blyp.config.ts`, `blyp.config.mts`, `blyp.config.cts`, `blyp.config.js`, `blyp.config.mjs`, `blyp.config.cjs`, `blyp.config.json`\n- Core imports: `logger`, `createStandaloneLogger`, `createStructuredLog`, `createError`, `parseError`\n- Related add-ons: `blyp-nextjs`, `blyp-react-router`, `blyp-nuxt`, `blyp-express`, `blyp-hono`, `blyp-elysia`, `blyp-workers`, `blyp-convex`, `blyp-client-expo`, `blyp-betterstack`, `blyp-databuddy`, `blyp-posthog`, `blyp-sentry`, `blyp-otlp`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-core/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-core\ndescription: Portable Blyp integration skill for installing @blyp/core, choosing the right runtime export, configuring blyp.config.*, wiring /inngest ingestion, and keeping server, browser, and Expo logging production-safe.\ncompatibility: Requires a JavaScript or TypeScript project using Bun, pnpm, npm, or Yarn.\n---\n\n# Blyp Core\n\n## What this skill is for\n\nUse this skill whenever an agent needs to add, review, or change Blyp logging in an application. This is the baseline skill for all Blyp work.\n\n## When to use it\n\n- Installing `@blyp/core` in a new project\n- Choosing the correct Blyp import path for the runtime\n- Adding or updating `blyp.config.*`\n- Enabling browser or Expo log ingestion\n- Preparing the project for Blyp connector add-ons or framework add-ons\n\n## Blyp-specific rules and constraints\n\n- The npm package name is `@blyp/core`.\n- Always choose the subpath that matches the runtime instead of forcing the root package everywhere.\n- Prefer shared project config in `blyp.config.ts`, `blyp.config.mts`, `blyp.config.cts`, `blyp.config.js`, `blyp.config.mjs`, `blyp.config.cjs`, or `blyp.config.json`.\n- Default client ingestion path is `/inngest`.\n- Browser and Expo connector delivery still posts to Blyp ingestion first. They do not send directly to PostHog, Sentry, Databuddy, or OTLP vendors.\n- Prefer production-safe defaults over the shortest demo snippet.\n- When client logging is enabled, verify that the mounted handler path matches the configured ingestion path exactly.\n- Treat unsupported presets as out of scope unless another Blyp skill explicitly covers them.\n\n## Required implementation steps\n\n1. Install `@blyp/core` with the package manager already used by the repo.\n2. Identify the runtime and select the matching Blyp entry:\n   - `@blyp/core` for root logger, standalone logger, config helpers, structured logs, and errors\n   - `@blyp/core/client` for browser logging\n   - `@blyp/core/expo` for Expo apps\n   - `@blyp/core/config` for isolate-safe `defineConfig()` when Convex or Workers will import `blyp.config.ts`\n   - `@blyp/core/<framework>` for framework adapters such as `nextjs`, `react-router`, `nuxt`, `express`, `hono`, `elysia`, `workers`, or `convex`\n3. Add or update `blyp.config.*` if the project needs shared log level, file logging, client ingestion, or connector configuration.\n4. If browser logging is enabled, keep the ingestion path aligned across config and server route mounting. Default to `/inngest` unless the repo already standardizes a different path.\n5. If connectors are involved, configure them on the server side first. Client and Expo requests depend on server connector configuration.\n6. Reuse existing Blyp helpers where possible:\n   - `logger`\n   - `createStandaloneLogger`\n   - `createStructuredLog`\n   - `createError`\n   - `parseError`\n7. Add a framework or connector add-on skill when runtime-specific behavior matters.\n\n## Verification checklist\n\n- `@blyp/core` is installed and imported from the correct subpath\n- Any shared Blyp settings live in a supported `blyp.config.*` file\n- Client ingestion uses the expected path, defaulting to `/inngest`\n- Browser or Expo connector requests are backed by server connector configuration\n- No framework-specific wiring is guessed when an adapter-specific Blyp skill exists\n- The final implementation favors safe config and correct handler mounting over the smallest possible snippet\n\n## References\n\n- Package: `@blyp/core`\n- Config files: `blyp.config.ts`, `blyp.config.mts`, `blyp.config.cts`, `blyp.config.js`, `blyp.config.mjs`, `blyp.config.cjs`, `blyp.config.json`\n- Core imports: `logger`, `createStandaloneLogger`, `createStructuredLog`, `createError`, `parseError`\n- Related add-ons: `blyp-nextjs`, `blyp-react-router`, `blyp-nuxt`, `blyp-express`, `blyp-hono`, `blyp-elysia`, `blyp-workers`, `blyp-convex`, `blyp-client-expo`, `blyp-betterstack`, `blyp-databuddy`, `blyp-posthog`, `blyp-sentry`, `blyp-otlp`\n"},"sha256":"0a34e9ef5b2248d2889d9e5c343ff284c2ff1f2f2b1abc3f45d47330ff39c3c3","digest":"sha256:0a34e9ef5b2248d2889d9e5c343ff284c2ff1f2f2b1abc3f45d47330ff39c3c3"}]},{"name":"blyp-databuddy","type":"skill-md","description":"Portable Blyp connector add-on skill for Databuddy using connectors.databuddy, auto or manual delivery, and browser or Expo forwarding through Blyp ingestion.","url":"/.well-known/agent-skills/blyp-databuddy/SKILL.md","digest":"sha256:2bd01873f0006c613ccf5cb5e410479eb4149ac02b74180d5a62d9b63962abab","content":{"text":"---\nname: blyp-databuddy\ndescription: Portable Blyp connector add-on skill for Databuddy using connectors.databuddy, auto or manual delivery, and browser or Expo forwarding through Blyp ingestion.\n---\n\n# Blyp Databuddy\n\n## What this skill is for\n\nUse this add-on when Blyp logs or handled errors should be forwarded into Databuddy.\n\n## When to use it\n\n- Configuring `connectors.databuddy`\n- Choosing `mode: \"auto\"` or `mode: \"manual\"`\n- Using Databuddy manual helper APIs\n- Supporting browser or Expo requests that ask Blyp to forward into Databuddy\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure Databuddy on the server in `connectors.databuddy`.\n- Supported delivery modes are `auto` and `manual`.\n- `apiKey` and `websiteId` are both required. Without both values, the connector remains `missing`.\n- Browser and Expo Databuddy requests still send to Blyp ingestion first.\n- In `auto` mode, Blyp forwards normal server logs automatically and captures handled server errors as Databuddy `error` events.\n- If manual control is required, use `@blyp/core/databuddy`.\n\n## Required implementation steps\n\n1. Add or update `connectors.databuddy` in `blyp.config.*`.\n2. Set `enabled: true` and choose `mode: \"auto\"` or `mode: \"manual\"`.\n3. Provide `apiKey`, `websiteId`, and optional delivery settings such as `enableBatching`.\n4. If manual control is required, import from `@blyp/core/databuddy` instead of assuming auto delivery.\n5. If browser or Expo code requests `connector: \"databuddy\"`, verify the server connector is configured first.\n\n## Verification checklist\n\n- `connectors.databuddy` exists in `blyp.config.*`\n- `apiKey` and `websiteId` are both present\n- The chosen mode is explicit: `auto` or `manual`\n- Browser or Expo Databuddy forwarding still targets Blyp ingestion first\n- Manual code imports from `@blyp/core/databuddy` when auto mode is not desired\n\n## References\n\n- Config key: `connectors.databuddy`\n- Manual import path: `@blyp/core/databuddy`\n- Manual APIs: `createDatabuddyLogger()`, `createStructuredDatabuddyLogger()`, `createDatabuddyErrorTracker()`, `captureDatabuddyException()`\n"},"sha256":"2bd01873f0006c613ccf5cb5e410479eb4149ac02b74180d5a62d9b63962abab","skillDocument":"---\nname: blyp-databuddy\ndescription: Portable Blyp connector add-on skill for Databuddy using connectors.databuddy, auto or manual delivery, and browser or Expo forwarding through Blyp ingestion.\n---\n\n# Blyp Databuddy\n\n## What this skill is for\n\nUse this add-on when Blyp logs or handled errors should be forwarded into Databuddy.\n\n## When to use it\n\n- Configuring `connectors.databuddy`\n- Choosing `mode: \"auto\"` or `mode: \"manual\"`\n- Using Databuddy manual helper APIs\n- Supporting browser or Expo requests that ask Blyp to forward into Databuddy\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure Databuddy on the server in `connectors.databuddy`.\n- Supported delivery modes are `auto` and `manual`.\n- `apiKey` and `websiteId` are both required. Without both values, the connector remains `missing`.\n- Browser and Expo Databuddy requests still send to Blyp ingestion first.\n- In `auto` mode, Blyp forwards normal server logs automatically and captures handled server errors as Databuddy `error` events.\n- If manual control is required, use `@blyp/core/databuddy`.\n\n## Required implementation steps\n\n1. Add or update `connectors.databuddy` in `blyp.config.*`.\n2. Set `enabled: true` and choose `mode: \"auto\"` or `mode: \"manual\"`.\n3. Provide `apiKey`, `websiteId`, and optional delivery settings such as `enableBatching`.\n4. If manual control is required, import from `@blyp/core/databuddy` instead of assuming auto delivery.\n5. If browser or Expo code requests `connector: \"databuddy\"`, verify the server connector is configured first.\n\n## Verification checklist\n\n- `connectors.databuddy` exists in `blyp.config.*`\n- `apiKey` and `websiteId` are both present\n- The chosen mode is explicit: `auto` or `manual`\n- Browser or Expo Databuddy forwarding still targets Blyp ingestion first\n- Manual code imports from `@blyp/core/databuddy` when auto mode is not desired\n\n## References\n\n- Config key: `connectors.databuddy`\n- Manual import path: `@blyp/core/databuddy`\n- Manual APIs: `createDatabuddyLogger()`, `createStructuredDatabuddyLogger()`, `createDatabuddyErrorTracker()`, `captureDatabuddyException()`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-databuddy/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-databuddy\ndescription: Portable Blyp connector add-on skill for Databuddy using connectors.databuddy, auto or manual delivery, and browser or Expo forwarding through Blyp ingestion.\n---\n\n# Blyp Databuddy\n\n## What this skill is for\n\nUse this add-on when Blyp logs or handled errors should be forwarded into Databuddy.\n\n## When to use it\n\n- Configuring `connectors.databuddy`\n- Choosing `mode: \"auto\"` or `mode: \"manual\"`\n- Using Databuddy manual helper APIs\n- Supporting browser or Expo requests that ask Blyp to forward into Databuddy\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure Databuddy on the server in `connectors.databuddy`.\n- Supported delivery modes are `auto` and `manual`.\n- `apiKey` and `websiteId` are both required. Without both values, the connector remains `missing`.\n- Browser and Expo Databuddy requests still send to Blyp ingestion first.\n- In `auto` mode, Blyp forwards normal server logs automatically and captures handled server errors as Databuddy `error` events.\n- If manual control is required, use `@blyp/core/databuddy`.\n\n## Required implementation steps\n\n1. Add or update `connectors.databuddy` in `blyp.config.*`.\n2. Set `enabled: true` and choose `mode: \"auto\"` or `mode: \"manual\"`.\n3. Provide `apiKey`, `websiteId`, and optional delivery settings such as `enableBatching`.\n4. If manual control is required, import from `@blyp/core/databuddy` instead of assuming auto delivery.\n5. If browser or Expo code requests `connector: \"databuddy\"`, verify the server connector is configured first.\n\n## Verification checklist\n\n- `connectors.databuddy` exists in `blyp.config.*`\n- `apiKey` and `websiteId` are both present\n- The chosen mode is explicit: `auto` or `manual`\n- Browser or Expo Databuddy forwarding still targets Blyp ingestion first\n- Manual code imports from `@blyp/core/databuddy` when auto mode is not desired\n\n## References\n\n- Config key: `connectors.databuddy`\n- Manual import path: `@blyp/core/databuddy`\n- Manual APIs: `createDatabuddyLogger()`, `createStructuredDatabuddyLogger()`, `createDatabuddyErrorTracker()`, `captureDatabuddyException()`\n"},"sha256":"2bd01873f0006c613ccf5cb5e410479eb4149ac02b74180d5a62d9b63962abab","digest":"sha256:2bd01873f0006c613ccf5cb5e410479eb4149ac02b74180d5a62d9b63962abab"}]},{"name":"blyp-elysia","type":"skill-md","description":"Portable Blyp add-on skill for Elysia services using @blyp/core/elysia, createLogger() as a plugin, and ctx.log for request-scoped logging.","url":"/.well-known/agent-skills/blyp-elysia/SKILL.md","digest":"sha256:77eb2772ef11cb4b10b5babc580586e5364a34ee8fe9e72f19f84cd71da5e3b6","content":{"text":"---\nname: blyp-elysia\ndescription: Portable Blyp add-on skill for Elysia services using @blyp/core/elysia, createLogger() as a plugin, and ctx.log for request-scoped logging.\n---\n\n# Blyp Elysia\n\n## What this skill is for\n\nUse this add-on when Blyp is being wired into an Elysia application.\n\n## When to use it\n\n- Adding Blyp as an Elysia plugin\n- Logging inside Elysia handlers\n- Enabling client ingestion in an Elysia server\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Import from `@blyp/core/elysia`.\n- Use `createLogger()` as an Elysia plugin via `.use(...)`.\n- Access the request logger as `ctx.log` or `{ log }` in handlers.\n- Keep ingestion behavior aligned with the configured path when client logging is enabled.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/elysia`.\n2. Add the plugin with `.use(createLogger(...))`.\n3. Prefer `ctx.log` for request-scoped logging instead of a root logger inside handlers.\n4. Keep any request metadata additions in `customProps`.\n5. If browser ingestion is enabled, verify the configured path is the one Elysia accepts for client logs.\n\n## Verification checklist\n\n- The app imports from `@blyp/core/elysia`\n- Blyp is mounted through `.use(createLogger(...))`\n- Handlers log with `ctx.log`\n- Client ingestion path is consistent with config\n\n## References\n\n- Import path: `@blyp/core/elysia`\n- Main API: `createLogger()`\n- Request logger: `ctx.log`\n"},"sha256":"77eb2772ef11cb4b10b5babc580586e5364a34ee8fe9e72f19f84cd71da5e3b6","skillDocument":"---\nname: blyp-elysia\ndescription: Portable Blyp add-on skill for Elysia services using @blyp/core/elysia, createLogger() as a plugin, and ctx.log for request-scoped logging.\n---\n\n# Blyp Elysia\n\n## What this skill is for\n\nUse this add-on when Blyp is being wired into an Elysia application.\n\n## When to use it\n\n- Adding Blyp as an Elysia plugin\n- Logging inside Elysia handlers\n- Enabling client ingestion in an Elysia server\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Import from `@blyp/core/elysia`.\n- Use `createLogger()` as an Elysia plugin via `.use(...)`.\n- Access the request logger as `ctx.log` or `{ log }` in handlers.\n- Keep ingestion behavior aligned with the configured path when client logging is enabled.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/elysia`.\n2. Add the plugin with `.use(createLogger(...))`.\n3. Prefer `ctx.log` for request-scoped logging instead of a root logger inside handlers.\n4. Keep any request metadata additions in `customProps`.\n5. If browser ingestion is enabled, verify the configured path is the one Elysia accepts for client logs.\n\n## Verification checklist\n\n- The app imports from `@blyp/core/elysia`\n- Blyp is mounted through `.use(createLogger(...))`\n- Handlers log with `ctx.log`\n- Client ingestion path is consistent with config\n\n## References\n\n- Import path: `@blyp/core/elysia`\n- Main API: `createLogger()`\n- Request logger: `ctx.log`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-elysia/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-elysia\ndescription: Portable Blyp add-on skill for Elysia services using @blyp/core/elysia, createLogger() as a plugin, and ctx.log for request-scoped logging.\n---\n\n# Blyp Elysia\n\n## What this skill is for\n\nUse this add-on when Blyp is being wired into an Elysia application.\n\n## When to use it\n\n- Adding Blyp as an Elysia plugin\n- Logging inside Elysia handlers\n- Enabling client ingestion in an Elysia server\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Import from `@blyp/core/elysia`.\n- Use `createLogger()` as an Elysia plugin via `.use(...)`.\n- Access the request logger as `ctx.log` or `{ log }` in handlers.\n- Keep ingestion behavior aligned with the configured path when client logging is enabled.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/elysia`.\n2. Add the plugin with `.use(createLogger(...))`.\n3. Prefer `ctx.log` for request-scoped logging instead of a root logger inside handlers.\n4. Keep any request metadata additions in `customProps`.\n5. If browser ingestion is enabled, verify the configured path is the one Elysia accepts for client logs.\n\n## Verification checklist\n\n- The app imports from `@blyp/core/elysia`\n- Blyp is mounted through `.use(createLogger(...))`\n- Handlers log with `ctx.log`\n- Client ingestion path is consistent with config\n\n## References\n\n- Import path: `@blyp/core/elysia`\n- Main API: `createLogger()`\n- Request logger: `ctx.log`\n"},"sha256":"77eb2772ef11cb4b10b5babc580586e5364a34ee8fe9e72f19f84cd71da5e3b6","digest":"sha256:77eb2772ef11cb4b10b5babc580586e5364a34ee8fe9e72f19f84cd71da5e3b6"}]},{"name":"blyp-express","type":"skill-md","description":"Portable Blyp add-on skill for Express apps using @blyp/core/express, req.blypLog, and createExpressErrorLogger() in the correct middleware order.","url":"/.well-known/agent-skills/blyp-express/SKILL.md","digest":"sha256:975c981b4a236763f5e18a3cbe339bf9706a7350f21e555efeb08c954dcffdac","content":{"text":"---\nname: blyp-express\ndescription: Portable Blyp add-on skill for Express apps using @blyp/core/express, req.blypLog, and createExpressErrorLogger() in the correct middleware order.\n---\n\n# Blyp Express\n\n## What this skill is for\n\nUse this add-on when the project runs on Express and needs Blyp middleware, request logging, or HTTP error logging.\n\n## When to use it\n\n- Adding Blyp to an Express app or router\n- Reading the request logger from `req.blypLog`\n- Enabling browser ingestion in an Express server\n- Fixing middleware order so Blyp can emit `http_error` records\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Import from `@blyp/core/express`.\n- Use `createLogger()` as standard Express middleware.\n- Use `req.blypLog` for request-scoped logging.\n- `createExpressErrorLogger()` must run before the app's final error handler so Blyp can capture thrown errors on `res.locals`.\n\n## Required implementation steps\n\n1. Import `createLogger` and `createExpressErrorLogger` from `@blyp/core/express`.\n2. Mount `createLogger(...)` before routes that need request-scoped logging.\n3. Replace ad hoc request log access with `req.blypLog`.\n4. If browser ingestion is enabled, keep the configured path aligned with the mounted Blyp middleware behavior.\n5. Mount `createExpressErrorLogger()` before the terminal error responder middleware.\n6. Leave the application's final error serialization in place after Blyp's error logger middleware.\n\n## Verification checklist\n\n- The server imports from `@blyp/core/express`\n- Routes log through `req.blypLog`\n- `createLogger()` runs before routes\n- `createExpressErrorLogger()` runs before the final error handler\n- Error responses still work after Blyp middleware is inserted\n\n## References\n\n- Import path: `@blyp/core/express`\n- Main APIs: `createLogger()`, `createExpressErrorLogger()`\n- Request logger: `req.blypLog`\n"},"sha256":"975c981b4a236763f5e18a3cbe339bf9706a7350f21e555efeb08c954dcffdac","skillDocument":"---\nname: blyp-express\ndescription: Portable Blyp add-on skill for Express apps using @blyp/core/express, req.blypLog, and createExpressErrorLogger() in the correct middleware order.\n---\n\n# Blyp Express\n\n## What this skill is for\n\nUse this add-on when the project runs on Express and needs Blyp middleware, request logging, or HTTP error logging.\n\n## When to use it\n\n- Adding Blyp to an Express app or router\n- Reading the request logger from `req.blypLog`\n- Enabling browser ingestion in an Express server\n- Fixing middleware order so Blyp can emit `http_error` records\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Import from `@blyp/core/express`.\n- Use `createLogger()` as standard Express middleware.\n- Use `req.blypLog` for request-scoped logging.\n- `createExpressErrorLogger()` must run before the app's final error handler so Blyp can capture thrown errors on `res.locals`.\n\n## Required implementation steps\n\n1. Import `createLogger` and `createExpressErrorLogger` from `@blyp/core/express`.\n2. Mount `createLogger(...)` before routes that need request-scoped logging.\n3. Replace ad hoc request log access with `req.blypLog`.\n4. If browser ingestion is enabled, keep the configured path aligned with the mounted Blyp middleware behavior.\n5. Mount `createExpressErrorLogger()` before the terminal error responder middleware.\n6. Leave the application's final error serialization in place after Blyp's error logger middleware.\n\n## Verification checklist\n\n- The server imports from `@blyp/core/express`\n- Routes log through `req.blypLog`\n- `createLogger()` runs before routes\n- `createExpressErrorLogger()` runs before the final error handler\n- Error responses still work after Blyp middleware is inserted\n\n## References\n\n- Import path: `@blyp/core/express`\n- Main APIs: `createLogger()`, `createExpressErrorLogger()`\n- Request logger: `req.blypLog`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-express/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-express\ndescription: Portable Blyp add-on skill for Express apps using @blyp/core/express, req.blypLog, and createExpressErrorLogger() in the correct middleware order.\n---\n\n# Blyp Express\n\n## What this skill is for\n\nUse this add-on when the project runs on Express and needs Blyp middleware, request logging, or HTTP error logging.\n\n## When to use it\n\n- Adding Blyp to an Express app or router\n- Reading the request logger from `req.blypLog`\n- Enabling browser ingestion in an Express server\n- Fixing middleware order so Blyp can emit `http_error` records\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Import from `@blyp/core/express`.\n- Use `createLogger()` as standard Express middleware.\n- Use `req.blypLog` for request-scoped logging.\n- `createExpressErrorLogger()` must run before the app's final error handler so Blyp can capture thrown errors on `res.locals`.\n\n## Required implementation steps\n\n1. Import `createLogger` and `createExpressErrorLogger` from `@blyp/core/express`.\n2. Mount `createLogger(...)` before routes that need request-scoped logging.\n3. Replace ad hoc request log access with `req.blypLog`.\n4. If browser ingestion is enabled, keep the configured path aligned with the mounted Blyp middleware behavior.\n5. Mount `createExpressErrorLogger()` before the terminal error responder middleware.\n6. Leave the application's final error serialization in place after Blyp's error logger middleware.\n\n## Verification checklist\n\n- The server imports from `@blyp/core/express`\n- Routes log through `req.blypLog`\n- `createLogger()` runs before routes\n- `createExpressErrorLogger()` runs before the final error handler\n- Error responses still work after Blyp middleware is inserted\n\n## References\n\n- Import path: `@blyp/core/express`\n- Main APIs: `createLogger()`, `createExpressErrorLogger()`\n- Request logger: `req.blypLog`\n"},"sha256":"975c981b4a236763f5e18a3cbe339bf9706a7350f21e555efeb08c954dcffdac","digest":"sha256:975c981b4a236763f5e18a3cbe339bf9706a7350f21e555efeb08c954dcffdac"}]},{"name":"blyp-hono","type":"skill-md","description":"Portable Blyp add-on skill for Hono apps using @blyp/core/hono, middleware on *, context.get(\"blypLog\"), and automatic /inngest interception when enabled.","url":"/.well-known/agent-skills/blyp-hono/SKILL.md","digest":"sha256:b24795b135134151fc8fa1bce337294089848a9b0624ef77a4324b1af871fb22","content":{"text":"---\nname: blyp-hono\ndescription: Portable Blyp add-on skill for Hono apps using @blyp/core/hono, middleware on *, context.get(\"blypLog\"), and automatic /inngest interception when enabled.\n---\n\n# Blyp Hono\n\n## What this skill is for\n\nUse this add-on when Blyp needs to run inside a Hono application.\n\n## When to use it\n\n- Mounting Blyp as Hono middleware\n- Reading the request logger from context variables\n- Enabling client ingestion in a Hono server\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Import from `@blyp/core/hono`.\n- Mount the middleware on `\"*\"` unless the repo intentionally limits coverage.\n- Read the request logger with `context.get(\"blypLog\")`.\n- When client logging is enabled, Blyp automatically intercepts `POST /inngest` on the configured path.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/hono`.\n2. Mount the middleware with `app.use(\"*\", createLogger(...))` unless the repo has a narrower route strategy.\n3. Replace request-scoped log access with `context.get(\"blypLog\")`.\n4. Keep custom props and ignore path logic inside the Blyp middleware config rather than in ad hoc wrappers.\n5. If client ingestion is enabled, verify that the configured path still matches the expected route.\n\n## Verification checklist\n\n- The app imports from `@blyp/core/hono`\n- Blyp middleware is mounted on `\"*\"` or an intentional equivalent\n- Request logging uses `context.get(\"blypLog\")`\n- Client ingestion path remains aligned with the Blyp config\n\n## References\n\n- Import path: `@blyp/core/hono`\n- Main API: `createLogger()`\n- Request logger: `context.get(\"blypLog\")`\n"},"sha256":"b24795b135134151fc8fa1bce337294089848a9b0624ef77a4324b1af871fb22","skillDocument":"---\nname: blyp-hono\ndescription: Portable Blyp add-on skill for Hono apps using @blyp/core/hono, middleware on *, context.get(\"blypLog\"), and automatic /inngest interception when enabled.\n---\n\n# Blyp Hono\n\n## What this skill is for\n\nUse this add-on when Blyp needs to run inside a Hono application.\n\n## When to use it\n\n- Mounting Blyp as Hono middleware\n- Reading the request logger from context variables\n- Enabling client ingestion in a Hono server\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Import from `@blyp/core/hono`.\n- Mount the middleware on `\"*\"` unless the repo intentionally limits coverage.\n- Read the request logger with `context.get(\"blypLog\")`.\n- When client logging is enabled, Blyp automatically intercepts `POST /inngest` on the configured path.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/hono`.\n2. Mount the middleware with `app.use(\"*\", createLogger(...))` unless the repo has a narrower route strategy.\n3. Replace request-scoped log access with `context.get(\"blypLog\")`.\n4. Keep custom props and ignore path logic inside the Blyp middleware config rather than in ad hoc wrappers.\n5. If client ingestion is enabled, verify that the configured path still matches the expected route.\n\n## Verification checklist\n\n- The app imports from `@blyp/core/hono`\n- Blyp middleware is mounted on `\"*\"` or an intentional equivalent\n- Request logging uses `context.get(\"blypLog\")`\n- Client ingestion path remains aligned with the Blyp config\n\n## References\n\n- Import path: `@blyp/core/hono`\n- Main API: `createLogger()`\n- Request logger: `context.get(\"blypLog\")`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-hono/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-hono\ndescription: Portable Blyp add-on skill for Hono apps using @blyp/core/hono, middleware on *, context.get(\"blypLog\"), and automatic /inngest interception when enabled.\n---\n\n# Blyp Hono\n\n## What this skill is for\n\nUse this add-on when Blyp needs to run inside a Hono application.\n\n## When to use it\n\n- Mounting Blyp as Hono middleware\n- Reading the request logger from context variables\n- Enabling client ingestion in a Hono server\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Import from `@blyp/core/hono`.\n- Mount the middleware on `\"*\"` unless the repo intentionally limits coverage.\n- Read the request logger with `context.get(\"blypLog\")`.\n- When client logging is enabled, Blyp automatically intercepts `POST /inngest` on the configured path.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/hono`.\n2. Mount the middleware with `app.use(\"*\", createLogger(...))` unless the repo has a narrower route strategy.\n3. Replace request-scoped log access with `context.get(\"blypLog\")`.\n4. Keep custom props and ignore path logic inside the Blyp middleware config rather than in ad hoc wrappers.\n5. If client ingestion is enabled, verify that the configured path still matches the expected route.\n\n## Verification checklist\n\n- The app imports from `@blyp/core/hono`\n- Blyp middleware is mounted on `\"*\"` or an intentional equivalent\n- Request logging uses `context.get(\"blypLog\")`\n- Client ingestion path remains aligned with the Blyp config\n\n## References\n\n- Import path: `@blyp/core/hono`\n- Main API: `createLogger()`\n- Request logger: `context.get(\"blypLog\")`\n"},"sha256":"b24795b135134151fc8fa1bce337294089848a9b0624ef77a4324b1af871fb22","digest":"sha256:b24795b135134151fc8fa1bce337294089848a9b0624ef77a4324b1af871fb22"}]},{"name":"blyp-nextjs","type":"skill-md","description":"Portable Blyp add-on skill for Next.js App Router projects using @blyp/core/nextjs, withLogger(), and clientLogHandler on the configured ingestion path.","url":"/.well-known/agent-skills/blyp-nextjs/SKILL.md","digest":"sha256:885cfdc83128ae80f6e666b0e007af78c8d15231fd4a7b97eb9a92181b4d8303","content":{"text":"---\nname: blyp-nextjs\ndescription: Portable Blyp add-on skill for Next.js App Router projects using @blyp/core/nextjs, withLogger(), and clientLogHandler on the configured ingestion path.\n---\n\n# Blyp Next.js\n\n## What this skill is for\n\nUse this add-on when the project uses Next.js App Router and needs Blyp route logging or client ingestion.\n\n## When to use it\n\n- Adding Blyp to `app/**/route.ts`\n- Wrapping handlers with `withLogger(...)`\n- Mounting `clientLogHandler` for browser logging\n- Auditing whether the configured ingestion path matches the mounted route\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first and keep its baseline rules in force.\n- Import from `@blyp/core/nextjs`.\n- Create the adapter with `createLogger()`.\n- Wrap App Router handlers with `nextLogger.withLogger(...)`.\n- Mount `nextLogger.clientLogHandler` on the same path configured for client logging, usually `/inngest`.\n- If the mounted route path does not match the configured ingestion path, Blyp returns a `500` mismatch response.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/nextjs`.\n2. Create a shared adapter instance if the project benefits from one.\n3. Wrap each route handler that should expose request logging with `withLogger(...)`.\n4. Use the injected `{ log }` helper inside the wrapped handler instead of inventing a parallel logger.\n5. If browser ingestion is enabled, create the route file for the configured path and export `POST = nextLogger.clientLogHandler`.\n6. Keep `blyp.config.*` and the mounted route aligned on the same ingestion path.\n\n## Verification checklist\n\n- The project imports from `@blyp/core/nextjs`\n- Route handlers use `withLogger(...)`\n- Request logging reads from the injected `log`\n- The ingestion route exports `clientLogHandler`\n- Mounted path and configured path match exactly\n\n## References\n\n- Import path: `@blyp/core/nextjs`\n- Main API: `createLogger()`\n- Handler wrapper: `withLogger(...)`\n- Client ingestion handler: `clientLogHandler`\n"},"sha256":"885cfdc83128ae80f6e666b0e007af78c8d15231fd4a7b97eb9a92181b4d8303","skillDocument":"---\nname: blyp-nextjs\ndescription: Portable Blyp add-on skill for Next.js App Router projects using @blyp/core/nextjs, withLogger(), and clientLogHandler on the configured ingestion path.\n---\n\n# Blyp Next.js\n\n## What this skill is for\n\nUse this add-on when the project uses Next.js App Router and needs Blyp route logging or client ingestion.\n\n## When to use it\n\n- Adding Blyp to `app/**/route.ts`\n- Wrapping handlers with `withLogger(...)`\n- Mounting `clientLogHandler` for browser logging\n- Auditing whether the configured ingestion path matches the mounted route\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first and keep its baseline rules in force.\n- Import from `@blyp/core/nextjs`.\n- Create the adapter with `createLogger()`.\n- Wrap App Router handlers with `nextLogger.withLogger(...)`.\n- Mount `nextLogger.clientLogHandler` on the same path configured for client logging, usually `/inngest`.\n- If the mounted route path does not match the configured ingestion path, Blyp returns a `500` mismatch response.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/nextjs`.\n2. Create a shared adapter instance if the project benefits from one.\n3. Wrap each route handler that should expose request logging with `withLogger(...)`.\n4. Use the injected `{ log }` helper inside the wrapped handler instead of inventing a parallel logger.\n5. If browser ingestion is enabled, create the route file for the configured path and export `POST = nextLogger.clientLogHandler`.\n6. Keep `blyp.config.*` and the mounted route aligned on the same ingestion path.\n\n## Verification checklist\n\n- The project imports from `@blyp/core/nextjs`\n- Route handlers use `withLogger(...)`\n- Request logging reads from the injected `log`\n- The ingestion route exports `clientLogHandler`\n- Mounted path and configured path match exactly\n\n## References\n\n- Import path: `@blyp/core/nextjs`\n- Main API: `createLogger()`\n- Handler wrapper: `withLogger(...)`\n- Client ingestion handler: `clientLogHandler`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-nextjs/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-nextjs\ndescription: Portable Blyp add-on skill for Next.js App Router projects using @blyp/core/nextjs, withLogger(), and clientLogHandler on the configured ingestion path.\n---\n\n# Blyp Next.js\n\n## What this skill is for\n\nUse this add-on when the project uses Next.js App Router and needs Blyp route logging or client ingestion.\n\n## When to use it\n\n- Adding Blyp to `app/**/route.ts`\n- Wrapping handlers with `withLogger(...)`\n- Mounting `clientLogHandler` for browser logging\n- Auditing whether the configured ingestion path matches the mounted route\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first and keep its baseline rules in force.\n- Import from `@blyp/core/nextjs`.\n- Create the adapter with `createLogger()`.\n- Wrap App Router handlers with `nextLogger.withLogger(...)`.\n- Mount `nextLogger.clientLogHandler` on the same path configured for client logging, usually `/inngest`.\n- If the mounted route path does not match the configured ingestion path, Blyp returns a `500` mismatch response.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/nextjs`.\n2. Create a shared adapter instance if the project benefits from one.\n3. Wrap each route handler that should expose request logging with `withLogger(...)`.\n4. Use the injected `{ log }` helper inside the wrapped handler instead of inventing a parallel logger.\n5. If browser ingestion is enabled, create the route file for the configured path and export `POST = nextLogger.clientLogHandler`.\n6. Keep `blyp.config.*` and the mounted route aligned on the same ingestion path.\n\n## Verification checklist\n\n- The project imports from `@blyp/core/nextjs`\n- Route handlers use `withLogger(...)`\n- Request logging reads from the injected `log`\n- The ingestion route exports `clientLogHandler`\n- Mounted path and configured path match exactly\n\n## References\n\n- Import path: `@blyp/core/nextjs`\n- Main API: `createLogger()`\n- Handler wrapper: `withLogger(...)`\n- Client ingestion handler: `clientLogHandler`\n"},"sha256":"885cfdc83128ae80f6e666b0e007af78c8d15231fd4a7b97eb9a92181b4d8303","digest":"sha256:885cfdc83128ae80f6e666b0e007af78c8d15231fd4a7b97eb9a92181b4d8303"}]},{"name":"blyp-nuxt","type":"skill-md","description":"Portable Blyp add-on skill for Nuxt apps using @blyp/core/nuxt, serverPlugin, getLogger(event), and clientLogHandler in server API routes.","url":"/.well-known/agent-skills/blyp-nuxt/SKILL.md","digest":"sha256:9c943c3d2e95bb0f81f8a0d4003a87326a14baee8ac1364b597657de75290fea","content":{"text":"---\nname: blyp-nuxt\ndescription: Portable Blyp add-on skill for Nuxt apps using @blyp/core/nuxt, serverPlugin, getLogger(event), and clientLogHandler in server API routes.\n---\n\n# Blyp Nuxt\n\n## What this skill is for\n\nUse this add-on when the project uses Nuxt and needs Blyp request logging or browser ingestion.\n\n## When to use it\n\n- Registering Blyp in `server/plugins`\n- Reading the request-scoped logger with `getLogger(event)`\n- Mounting `clientLogHandler` in `server/api/*.post.ts`\n- Keeping Nuxt ingestion routes aligned with `blyp.config.*`\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first and keep its baseline rules in force.\n- Import from `@blyp/core/nuxt`.\n- Create the adapter with `createLogger()`.\n- Export `nuxtLogger.serverPlugin` from a Nuxt server plugin file.\n- Use `nuxtLogger.getLogger(event)` for request-scoped logging inside Nuxt server handlers.\n- Mount `nuxtLogger.clientLogHandler` on the configured ingestion path, usually `/inngest`.\n- Nuxt reuses Blyp's Nitro request lifecycle internally, so follow Nitro-style event handling rather than inventing a custom adapter layer.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/nuxt`.\n2. Create a shared adapter instance if the project benefits from one.\n3. Export `nuxtLogger.serverPlugin` from `server/plugins/blyp.ts` or the repo's equivalent Nuxt plugin location.\n4. Use `nuxtLogger.getLogger(event)` inside server handlers that need request-scoped logging.\n5. If browser ingestion is enabled, export `nuxtLogger.clientLogHandler` from the configured `server/api` route.\n6. Keep `blyp.config.*` and the mounted route aligned on the same ingestion path.\n\n## Verification checklist\n\n- The project imports from `@blyp/core/nuxt`\n- A server plugin exports `nuxtLogger.serverPlugin`\n- Request logging reads from `getLogger(event)`\n- The ingestion route exports `clientLogHandler`\n- Mounted path and configured path match exactly\n\n## References\n\n- Import path: `@blyp/core/nuxt`\n- Main API: `createLogger()`\n- Server plugin: `serverPlugin`\n- Request logger access: `getLogger(event)`\n- Client ingestion handler: `clientLogHandler`\n"},"sha256":"9c943c3d2e95bb0f81f8a0d4003a87326a14baee8ac1364b597657de75290fea","skillDocument":"---\nname: blyp-nuxt\ndescription: Portable Blyp add-on skill for Nuxt apps using @blyp/core/nuxt, serverPlugin, getLogger(event), and clientLogHandler in server API routes.\n---\n\n# Blyp Nuxt\n\n## What this skill is for\n\nUse this add-on when the project uses Nuxt and needs Blyp request logging or browser ingestion.\n\n## When to use it\n\n- Registering Blyp in `server/plugins`\n- Reading the request-scoped logger with `getLogger(event)`\n- Mounting `clientLogHandler` in `server/api/*.post.ts`\n- Keeping Nuxt ingestion routes aligned with `blyp.config.*`\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first and keep its baseline rules in force.\n- Import from `@blyp/core/nuxt`.\n- Create the adapter with `createLogger()`.\n- Export `nuxtLogger.serverPlugin` from a Nuxt server plugin file.\n- Use `nuxtLogger.getLogger(event)` for request-scoped logging inside Nuxt server handlers.\n- Mount `nuxtLogger.clientLogHandler` on the configured ingestion path, usually `/inngest`.\n- Nuxt reuses Blyp's Nitro request lifecycle internally, so follow Nitro-style event handling rather than inventing a custom adapter layer.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/nuxt`.\n2. Create a shared adapter instance if the project benefits from one.\n3. Export `nuxtLogger.serverPlugin` from `server/plugins/blyp.ts` or the repo's equivalent Nuxt plugin location.\n4. Use `nuxtLogger.getLogger(event)` inside server handlers that need request-scoped logging.\n5. If browser ingestion is enabled, export `nuxtLogger.clientLogHandler` from the configured `server/api` route.\n6. Keep `blyp.config.*` and the mounted route aligned on the same ingestion path.\n\n## Verification checklist\n\n- The project imports from `@blyp/core/nuxt`\n- A server plugin exports `nuxtLogger.serverPlugin`\n- Request logging reads from `getLogger(event)`\n- The ingestion route exports `clientLogHandler`\n- Mounted path and configured path match exactly\n\n## References\n\n- Import path: `@blyp/core/nuxt`\n- Main API: `createLogger()`\n- Server plugin: `serverPlugin`\n- Request logger access: `getLogger(event)`\n- Client ingestion handler: `clientLogHandler`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-nuxt/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-nuxt\ndescription: Portable Blyp add-on skill for Nuxt apps using @blyp/core/nuxt, serverPlugin, getLogger(event), and clientLogHandler in server API routes.\n---\n\n# Blyp Nuxt\n\n## What this skill is for\n\nUse this add-on when the project uses Nuxt and needs Blyp request logging or browser ingestion.\n\n## When to use it\n\n- Registering Blyp in `server/plugins`\n- Reading the request-scoped logger with `getLogger(event)`\n- Mounting `clientLogHandler` in `server/api/*.post.ts`\n- Keeping Nuxt ingestion routes aligned with `blyp.config.*`\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first and keep its baseline rules in force.\n- Import from `@blyp/core/nuxt`.\n- Create the adapter with `createLogger()`.\n- Export `nuxtLogger.serverPlugin` from a Nuxt server plugin file.\n- Use `nuxtLogger.getLogger(event)` for request-scoped logging inside Nuxt server handlers.\n- Mount `nuxtLogger.clientLogHandler` on the configured ingestion path, usually `/inngest`.\n- Nuxt reuses Blyp's Nitro request lifecycle internally, so follow Nitro-style event handling rather than inventing a custom adapter layer.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/nuxt`.\n2. Create a shared adapter instance if the project benefits from one.\n3. Export `nuxtLogger.serverPlugin` from `server/plugins/blyp.ts` or the repo's equivalent Nuxt plugin location.\n4. Use `nuxtLogger.getLogger(event)` inside server handlers that need request-scoped logging.\n5. If browser ingestion is enabled, export `nuxtLogger.clientLogHandler` from the configured `server/api` route.\n6. Keep `blyp.config.*` and the mounted route aligned on the same ingestion path.\n\n## Verification checklist\n\n- The project imports from `@blyp/core/nuxt`\n- A server plugin exports `nuxtLogger.serverPlugin`\n- Request logging reads from `getLogger(event)`\n- The ingestion route exports `clientLogHandler`\n- Mounted path and configured path match exactly\n\n## References\n\n- Import path: `@blyp/core/nuxt`\n- Main API: `createLogger()`\n- Server plugin: `serverPlugin`\n- Request logger access: `getLogger(event)`\n- Client ingestion handler: `clientLogHandler`\n"},"sha256":"9c943c3d2e95bb0f81f8a0d4003a87326a14baee8ac1364b597657de75290fea","digest":"sha256:9c943c3d2e95bb0f81f8a0d4003a87326a14baee8ac1364b597657de75290fea"}]},{"name":"blyp-otlp","type":"skill-md","description":"Portable Blyp connector add-on skill for named OTLP targets using connectors.otlp, explicit target names, auto or manual delivery modes, and client or Expo forwarding requests through Blyp.","url":"/.well-known/agent-skills/blyp-otlp/SKILL.md","digest":"sha256:c3ab5b25f2fcd82a28cd775fc28f36ef480a69ceb65e9ef5b1bccb5349947c78","content":{"text":"---\nname: blyp-otlp\ndescription: Portable Blyp connector add-on skill for named OTLP targets using connectors.otlp, explicit target names, auto or manual delivery modes, and client or Expo forwarding requests through Blyp.\n---\n\n# Blyp OTLP\n\n## What this skill is for\n\nUse this add-on when Blyp forwards logs to Grafana Cloud, Datadog, Honeycomb, or another OTLP-compatible target.\n\n## When to use it\n\n- Configuring `connectors.otlp`\n- Managing multiple named OTLP targets\n- Choosing `mode: \"auto\"` or `mode: \"manual\"`\n- Supporting browser or Expo requests that target a named OTLP connector\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure OTLP as an array under `connectors.otlp`.\n- Every OTLP target must have a unique `name`.\n- Supported delivery modes are `auto` and `manual`.\n- Manual OTLP APIs and client or Expo forwarding requests must target an explicit connector name.\n- Browser and Expo OTLP requests still go through Blyp ingestion first.\n- Convex action export uses `@blyp/core/convex`. Shared `blyp.config.ts` must import `defineConfig` from `@blyp/core/config`. Auto `connectors.otlp` targets and native vendor connectors are used.\n\n## Required implementation steps\n\n1. Add or update the `connectors.otlp` array in `blyp.config.*`.\n2. For each target, set `name`, `enabled`, `mode`, and `endpoint`.\n3. Add `auth`, `headers`, or `serviceName` if required by the backend.\n4. If manual control is required, import from `@blyp/core/otlp` and pass the target `name`.\n5. If browser or Expo code requests OTLP forwarding, use `{ type: \"otlp\", name: \"<target>\" }` and verify the named server connector exists.\n\n## Verification checklist\n\n- `connectors.otlp` is an array\n- Each OTLP target has a stable `name`\n- The chosen mode is explicit for each target\n- Manual or client forwarding paths always include a connector name\n- Browser or Expo forwarding still targets Blyp ingestion first\n\n## References\n\n- Config key: `connectors.otlp`\n- Manual import path: `@blyp/core/otlp`\n- Manual APIs: `createOtlpLogger()`, `createStructuredOtlpLogger()`\n"},"sha256":"c3ab5b25f2fcd82a28cd775fc28f36ef480a69ceb65e9ef5b1bccb5349947c78","skillDocument":"---\nname: blyp-otlp\ndescription: Portable Blyp connector add-on skill for named OTLP targets using connectors.otlp, explicit target names, auto or manual delivery modes, and client or Expo forwarding requests through Blyp.\n---\n\n# Blyp OTLP\n\n## What this skill is for\n\nUse this add-on when Blyp forwards logs to Grafana Cloud, Datadog, Honeycomb, or another OTLP-compatible target.\n\n## When to use it\n\n- Configuring `connectors.otlp`\n- Managing multiple named OTLP targets\n- Choosing `mode: \"auto\"` or `mode: \"manual\"`\n- Supporting browser or Expo requests that target a named OTLP connector\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure OTLP as an array under `connectors.otlp`.\n- Every OTLP target must have a unique `name`.\n- Supported delivery modes are `auto` and `manual`.\n- Manual OTLP APIs and client or Expo forwarding requests must target an explicit connector name.\n- Browser and Expo OTLP requests still go through Blyp ingestion first.\n- Convex action export uses `@blyp/core/convex`. Shared `blyp.config.ts` must import `defineConfig` from `@blyp/core/config`. Auto `connectors.otlp` targets and native vendor connectors are used.\n\n## Required implementation steps\n\n1. Add or update the `connectors.otlp` array in `blyp.config.*`.\n2. For each target, set `name`, `enabled`, `mode`, and `endpoint`.\n3. Add `auth`, `headers`, or `serviceName` if required by the backend.\n4. If manual control is required, import from `@blyp/core/otlp` and pass the target `name`.\n5. If browser or Expo code requests OTLP forwarding, use `{ type: \"otlp\", name: \"<target>\" }` and verify the named server connector exists.\n\n## Verification checklist\n\n- `connectors.otlp` is an array\n- Each OTLP target has a stable `name`\n- The chosen mode is explicit for each target\n- Manual or client forwarding paths always include a connector name\n- Browser or Expo forwarding still targets Blyp ingestion first\n\n## References\n\n- Config key: `connectors.otlp`\n- Manual import path: `@blyp/core/otlp`\n- Manual APIs: `createOtlpLogger()`, `createStructuredOtlpLogger()`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-otlp/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-otlp\ndescription: Portable Blyp connector add-on skill for named OTLP targets using connectors.otlp, explicit target names, auto or manual delivery modes, and client or Expo forwarding requests through Blyp.\n---\n\n# Blyp OTLP\n\n## What this skill is for\n\nUse this add-on when Blyp forwards logs to Grafana Cloud, Datadog, Honeycomb, or another OTLP-compatible target.\n\n## When to use it\n\n- Configuring `connectors.otlp`\n- Managing multiple named OTLP targets\n- Choosing `mode: \"auto\"` or `mode: \"manual\"`\n- Supporting browser or Expo requests that target a named OTLP connector\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure OTLP as an array under `connectors.otlp`.\n- Every OTLP target must have a unique `name`.\n- Supported delivery modes are `auto` and `manual`.\n- Manual OTLP APIs and client or Expo forwarding requests must target an explicit connector name.\n- Browser and Expo OTLP requests still go through Blyp ingestion first.\n- Convex action export uses `@blyp/core/convex`. Shared `blyp.config.ts` must import `defineConfig` from `@blyp/core/config`. Auto `connectors.otlp` targets and native vendor connectors are used.\n\n## Required implementation steps\n\n1. Add or update the `connectors.otlp` array in `blyp.config.*`.\n2. For each target, set `name`, `enabled`, `mode`, and `endpoint`.\n3. Add `auth`, `headers`, or `serviceName` if required by the backend.\n4. If manual control is required, import from `@blyp/core/otlp` and pass the target `name`.\n5. If browser or Expo code requests OTLP forwarding, use `{ type: \"otlp\", name: \"<target>\" }` and verify the named server connector exists.\n\n## Verification checklist\n\n- `connectors.otlp` is an array\n- Each OTLP target has a stable `name`\n- The chosen mode is explicit for each target\n- Manual or client forwarding paths always include a connector name\n- Browser or Expo forwarding still targets Blyp ingestion first\n\n## References\n\n- Config key: `connectors.otlp`\n- Manual import path: `@blyp/core/otlp`\n- Manual APIs: `createOtlpLogger()`, `createStructuredOtlpLogger()`\n"},"sha256":"c3ab5b25f2fcd82a28cd775fc28f36ef480a69ceb65e9ef5b1bccb5349947c78","digest":"sha256:c3ab5b25f2fcd82a28cd775fc28f36ef480a69ceb65e9ef5b1bccb5349947c78"}]},{"name":"blyp-posthog","type":"skill-md","description":"Portable Blyp connector add-on skill for PostHog using connectors.posthog, auto or manual delivery modes, and server-side error tracking that can receive browser or Expo forwarding requests through Blyp.","url":"/.well-known/agent-skills/blyp-posthog/SKILL.md","digest":"sha256:ec9b0c0d2f5b01c170c047c443c07d435718e177e027d65684d0173c64c75c81","content":{"text":"---\nname: blyp-posthog\ndescription: Portable Blyp connector add-on skill for PostHog using connectors.posthog, auto or manual delivery modes, and server-side error tracking that can receive browser or Expo forwarding requests through Blyp.\n---\n\n# Blyp PostHog\n\n## What this skill is for\n\nUse this add-on when Blyp logs or errors should be forwarded into PostHog.\n\n## When to use it\n\n- Configuring `connectors.posthog`\n- Choosing `mode: \"auto\"` or `mode: \"manual\"`\n- Enabling PostHog error tracking\n- Supporting browser or Expo requests that ask Blyp to forward into PostHog\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure PostHog on the server in `connectors.posthog`.\n- Supported delivery modes are `auto` and `manual`.\n- Error tracking is configured under `connectors.posthog.errorTracking`.\n- Browser and Expo PostHog requests still send to Blyp ingestion first.\n- Client `error` and `critical` logs are promoted to PostHog exceptions only when server-side PostHog error tracking is enabled in `auto` mode.\n\n## Required implementation steps\n\n1. Add or update `connectors.posthog` in `blyp.config.*`.\n2. Set `enabled: true` and choose `mode: \"auto\"` or `mode: \"manual\"`.\n3. Provide `projectKey` and optional `host` or `serviceName`.\n4. If the application wants Blyp-managed exception capture, configure `errorTracking`.\n5. If manual control is required, use `@blyp/core/posthog` APIs instead of assuming auto delivery.\n6. If browser or Expo code requests `connector: \"posthog\"`, verify the server connector is configured first.\n\n## Verification checklist\n\n- `connectors.posthog` exists in `blyp.config.*`\n- The chosen mode is explicit: `auto` or `manual`\n- Error tracking is configured intentionally when needed\n- Browser or Expo PostHog forwarding still targets Blyp ingestion first\n- Manual code imports from `@blyp/core/posthog` when auto mode is not desired\n\n## References\n\n- Config key: `connectors.posthog`\n- Manual import path: `@blyp/core/posthog`\n- Manual APIs: `createPosthogLogger()`, `createStructuredPosthogLogger()`, `createPosthogErrorTracker()`, `capturePosthogException()`\n"},"sha256":"ec9b0c0d2f5b01c170c047c443c07d435718e177e027d65684d0173c64c75c81","skillDocument":"---\nname: blyp-posthog\ndescription: Portable Blyp connector add-on skill for PostHog using connectors.posthog, auto or manual delivery modes, and server-side error tracking that can receive browser or Expo forwarding requests through Blyp.\n---\n\n# Blyp PostHog\n\n## What this skill is for\n\nUse this add-on when Blyp logs or errors should be forwarded into PostHog.\n\n## When to use it\n\n- Configuring `connectors.posthog`\n- Choosing `mode: \"auto\"` or `mode: \"manual\"`\n- Enabling PostHog error tracking\n- Supporting browser or Expo requests that ask Blyp to forward into PostHog\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure PostHog on the server in `connectors.posthog`.\n- Supported delivery modes are `auto` and `manual`.\n- Error tracking is configured under `connectors.posthog.errorTracking`.\n- Browser and Expo PostHog requests still send to Blyp ingestion first.\n- Client `error` and `critical` logs are promoted to PostHog exceptions only when server-side PostHog error tracking is enabled in `auto` mode.\n\n## Required implementation steps\n\n1. Add or update `connectors.posthog` in `blyp.config.*`.\n2. Set `enabled: true` and choose `mode: \"auto\"` or `mode: \"manual\"`.\n3. Provide `projectKey` and optional `host` or `serviceName`.\n4. If the application wants Blyp-managed exception capture, configure `errorTracking`.\n5. If manual control is required, use `@blyp/core/posthog` APIs instead of assuming auto delivery.\n6. If browser or Expo code requests `connector: \"posthog\"`, verify the server connector is configured first.\n\n## Verification checklist\n\n- `connectors.posthog` exists in `blyp.config.*`\n- The chosen mode is explicit: `auto` or `manual`\n- Error tracking is configured intentionally when needed\n- Browser or Expo PostHog forwarding still targets Blyp ingestion first\n- Manual code imports from `@blyp/core/posthog` when auto mode is not desired\n\n## References\n\n- Config key: `connectors.posthog`\n- Manual import path: `@blyp/core/posthog`\n- Manual APIs: `createPosthogLogger()`, `createStructuredPosthogLogger()`, `createPosthogErrorTracker()`, `capturePosthogException()`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-posthog/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-posthog\ndescription: Portable Blyp connector add-on skill for PostHog using connectors.posthog, auto or manual delivery modes, and server-side error tracking that can receive browser or Expo forwarding requests through Blyp.\n---\n\n# Blyp PostHog\n\n## What this skill is for\n\nUse this add-on when Blyp logs or errors should be forwarded into PostHog.\n\n## When to use it\n\n- Configuring `connectors.posthog`\n- Choosing `mode: \"auto\"` or `mode: \"manual\"`\n- Enabling PostHog error tracking\n- Supporting browser or Expo requests that ask Blyp to forward into PostHog\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure PostHog on the server in `connectors.posthog`.\n- Supported delivery modes are `auto` and `manual`.\n- Error tracking is configured under `connectors.posthog.errorTracking`.\n- Browser and Expo PostHog requests still send to Blyp ingestion first.\n- Client `error` and `critical` logs are promoted to PostHog exceptions only when server-side PostHog error tracking is enabled in `auto` mode.\n\n## Required implementation steps\n\n1. Add or update `connectors.posthog` in `blyp.config.*`.\n2. Set `enabled: true` and choose `mode: \"auto\"` or `mode: \"manual\"`.\n3. Provide `projectKey` and optional `host` or `serviceName`.\n4. If the application wants Blyp-managed exception capture, configure `errorTracking`.\n5. If manual control is required, use `@blyp/core/posthog` APIs instead of assuming auto delivery.\n6. If browser or Expo code requests `connector: \"posthog\"`, verify the server connector is configured first.\n\n## Verification checklist\n\n- `connectors.posthog` exists in `blyp.config.*`\n- The chosen mode is explicit: `auto` or `manual`\n- Error tracking is configured intentionally when needed\n- Browser or Expo PostHog forwarding still targets Blyp ingestion first\n- Manual code imports from `@blyp/core/posthog` when auto mode is not desired\n\n## References\n\n- Config key: `connectors.posthog`\n- Manual import path: `@blyp/core/posthog`\n- Manual APIs: `createPosthogLogger()`, `createStructuredPosthogLogger()`, `createPosthogErrorTracker()`, `capturePosthogException()`\n"},"sha256":"ec9b0c0d2f5b01c170c047c443c07d435718e177e027d65684d0173c64c75c81","digest":"sha256:ec9b0c0d2f5b01c170c047c443c07d435718e177e027d65684d0173c64c75c81"}]},{"name":"blyp-react-router","type":"skill-md","description":"Portable Blyp add-on skill for React Router apps using @blyp/core/react-router, middleware, request-scoped context logging, and clientLogHandler(request).","url":"/.well-known/agent-skills/blyp-react-router/SKILL.md","digest":"sha256:db76137c9f63acaf305a297fd05552f3596869c1650e59fcf9008bd8708fe701","content":{"text":"---\nname: blyp-react-router\ndescription: Portable Blyp add-on skill for React Router apps using @blyp/core/react-router, middleware, request-scoped context logging, and clientLogHandler(request).\n---\n\n# Blyp React Router\n\n## What this skill is for\n\nUse this add-on when the project uses React Router and needs Blyp request logging or browser ingestion.\n\n## When to use it\n\n- Adding Blyp to React Router middleware\n- Reading the request-scoped logger from `context`\n- Mounting `clientLogHandler(request)` in a route action\n- Auditing whether the mounted ingestion route matches the configured path\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first and keep its baseline rules in force.\n- Import from `@blyp/core/react-router`.\n- Create the adapter with `createLogger()`.\n- Mount `reactRouterLogger.middleware` in the React Router middleware array.\n- Use `reactRouterLogger.getLogger(context)` for request-scoped logging.\n- `getLogger(context)` falls back to the shared logger if no scoped logger is stored yet.\n- Mount `reactRouterLogger.clientLogHandler(request)` on the same path configured for client logging, usually `/inngest`.\n- If the mounted route path does not match the configured ingestion path, Blyp returns a `500` mismatch response.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/react-router`.\n2. Create a shared adapter instance if the project benefits from one.\n3. Add `reactRouterLogger.middleware` to the exported middleware array.\n4. Use `reactRouterLogger.getLogger(context)` inside loaders, actions, or middleware-aware handlers instead of inventing a parallel request logger.\n5. If browser ingestion is enabled, export a route action that calls `reactRouterLogger.clientLogHandler(request)`.\n6. Keep `blyp.config.*` and the mounted route aligned on the same ingestion path.\n\n## Verification checklist\n\n- The project imports from `@blyp/core/react-router`\n- Middleware includes `reactRouterLogger.middleware`\n- Request logging reads from `getLogger(context)`\n- The ingestion route action calls `clientLogHandler(request)`\n- Mounted path and configured path match exactly\n\n## References\n\n- Import path: `@blyp/core/react-router`\n- Main API: `createLogger()`\n- Middleware: `middleware`\n- Request logger access: `getLogger(context)`\n- Client ingestion handler: `clientLogHandler(request)`\n"},"sha256":"db76137c9f63acaf305a297fd05552f3596869c1650e59fcf9008bd8708fe701","skillDocument":"---\nname: blyp-react-router\ndescription: Portable Blyp add-on skill for React Router apps using @blyp/core/react-router, middleware, request-scoped context logging, and clientLogHandler(request).\n---\n\n# Blyp React Router\n\n## What this skill is for\n\nUse this add-on when the project uses React Router and needs Blyp request logging or browser ingestion.\n\n## When to use it\n\n- Adding Blyp to React Router middleware\n- Reading the request-scoped logger from `context`\n- Mounting `clientLogHandler(request)` in a route action\n- Auditing whether the mounted ingestion route matches the configured path\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first and keep its baseline rules in force.\n- Import from `@blyp/core/react-router`.\n- Create the adapter with `createLogger()`.\n- Mount `reactRouterLogger.middleware` in the React Router middleware array.\n- Use `reactRouterLogger.getLogger(context)` for request-scoped logging.\n- `getLogger(context)` falls back to the shared logger if no scoped logger is stored yet.\n- Mount `reactRouterLogger.clientLogHandler(request)` on the same path configured for client logging, usually `/inngest`.\n- If the mounted route path does not match the configured ingestion path, Blyp returns a `500` mismatch response.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/react-router`.\n2. Create a shared adapter instance if the project benefits from one.\n3. Add `reactRouterLogger.middleware` to the exported middleware array.\n4. Use `reactRouterLogger.getLogger(context)` inside loaders, actions, or middleware-aware handlers instead of inventing a parallel request logger.\n5. If browser ingestion is enabled, export a route action that calls `reactRouterLogger.clientLogHandler(request)`.\n6. Keep `blyp.config.*` and the mounted route aligned on the same ingestion path.\n\n## Verification checklist\n\n- The project imports from `@blyp/core/react-router`\n- Middleware includes `reactRouterLogger.middleware`\n- Request logging reads from `getLogger(context)`\n- The ingestion route action calls `clientLogHandler(request)`\n- Mounted path and configured path match exactly\n\n## References\n\n- Import path: `@blyp/core/react-router`\n- Main API: `createLogger()`\n- Middleware: `middleware`\n- Request logger access: `getLogger(context)`\n- Client ingestion handler: `clientLogHandler(request)`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-react-router/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-react-router\ndescription: Portable Blyp add-on skill for React Router apps using @blyp/core/react-router, middleware, request-scoped context logging, and clientLogHandler(request).\n---\n\n# Blyp React Router\n\n## What this skill is for\n\nUse this add-on when the project uses React Router and needs Blyp request logging or browser ingestion.\n\n## When to use it\n\n- Adding Blyp to React Router middleware\n- Reading the request-scoped logger from `context`\n- Mounting `clientLogHandler(request)` in a route action\n- Auditing whether the mounted ingestion route matches the configured path\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first and keep its baseline rules in force.\n- Import from `@blyp/core/react-router`.\n- Create the adapter with `createLogger()`.\n- Mount `reactRouterLogger.middleware` in the React Router middleware array.\n- Use `reactRouterLogger.getLogger(context)` for request-scoped logging.\n- `getLogger(context)` falls back to the shared logger if no scoped logger is stored yet.\n- Mount `reactRouterLogger.clientLogHandler(request)` on the same path configured for client logging, usually `/inngest`.\n- If the mounted route path does not match the configured ingestion path, Blyp returns a `500` mismatch response.\n\n## Required implementation steps\n\n1. Import `createLogger` from `@blyp/core/react-router`.\n2. Create a shared adapter instance if the project benefits from one.\n3. Add `reactRouterLogger.middleware` to the exported middleware array.\n4. Use `reactRouterLogger.getLogger(context)` inside loaders, actions, or middleware-aware handlers instead of inventing a parallel request logger.\n5. If browser ingestion is enabled, export a route action that calls `reactRouterLogger.clientLogHandler(request)`.\n6. Keep `blyp.config.*` and the mounted route aligned on the same ingestion path.\n\n## Verification checklist\n\n- The project imports from `@blyp/core/react-router`\n- Middleware includes `reactRouterLogger.middleware`\n- Request logging reads from `getLogger(context)`\n- The ingestion route action calls `clientLogHandler(request)`\n- Mounted path and configured path match exactly\n\n## References\n\n- Import path: `@blyp/core/react-router`\n- Main API: `createLogger()`\n- Middleware: `middleware`\n- Request logger access: `getLogger(context)`\n- Client ingestion handler: `clientLogHandler(request)`\n"},"sha256":"db76137c9f63acaf305a297fd05552f3596869c1650e59fcf9008bd8708fe701","digest":"sha256:db76137c9f63acaf305a297fd05552f3596869c1650e59fcf9008bd8708fe701"}]},{"name":"blyp-sentry","type":"skill-md","description":"Portable Blyp connector add-on skill for Sentry using connectors.sentry, auto or manual delivery modes, and browser or Expo forwarding requests through Blyp ingestion.","url":"/.well-known/agent-skills/blyp-sentry/SKILL.md","digest":"sha256:25df520225ec0a525e37960a262109df34f32945ae2a83e7531a76cc908ee80f","content":{"text":"---\nname: blyp-sentry\ndescription: Portable Blyp connector add-on skill for Sentry using connectors.sentry, auto or manual delivery modes, and browser or Expo forwarding requests through Blyp ingestion.\n---\n\n# Blyp Sentry\n\n## What this skill is for\n\nUse this add-on when Blyp logs or structured events should be forwarded into Sentry.\n\n## When to use it\n\n- Configuring `connectors.sentry`\n- Choosing `mode: \"auto\"` or `mode: \"manual\"`\n- Reusing an existing Sentry client in the application\n- Supporting browser or Expo requests that ask Blyp to forward into Sentry\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure Sentry on the server in `connectors.sentry`.\n- Supported delivery modes are `auto` and `manual`.\n- If Sentry is already initialized by the application, Blyp reuses the existing client.\n- Browser and Expo Sentry requests still go through Blyp ingestion first.\n\n## Required implementation steps\n\n1. Add or update `connectors.sentry` in `blyp.config.*`.\n2. Set `enabled: true` and choose `mode: \"auto\"` or `mode: \"manual\"`.\n3. Provide `dsn` and optional `environment` or `release`.\n4. If manual control is required, import from `@blyp/core/sentry`.\n5. If browser or Expo code requests `connector: \"sentry\"`, verify the server connector is configured first.\n\n## Verification checklist\n\n- `connectors.sentry` exists in `blyp.config.*`\n- The connector mode is explicit\n- Existing app-level Sentry initialization is not accidentally replaced\n- Browser or Expo forwarding still targets Blyp ingestion first\n- Manual code imports from `@blyp/core/sentry` when needed\n\n## References\n\n- Config key: `connectors.sentry`\n- Manual import path: `@blyp/core/sentry`\n- Manual APIs: `createSentryLogger()`, `createStructuredSentryLogger()`\n"},"sha256":"25df520225ec0a525e37960a262109df34f32945ae2a83e7531a76cc908ee80f","skillDocument":"---\nname: blyp-sentry\ndescription: Portable Blyp connector add-on skill for Sentry using connectors.sentry, auto or manual delivery modes, and browser or Expo forwarding requests through Blyp ingestion.\n---\n\n# Blyp Sentry\n\n## What this skill is for\n\nUse this add-on when Blyp logs or structured events should be forwarded into Sentry.\n\n## When to use it\n\n- Configuring `connectors.sentry`\n- Choosing `mode: \"auto\"` or `mode: \"manual\"`\n- Reusing an existing Sentry client in the application\n- Supporting browser or Expo requests that ask Blyp to forward into Sentry\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure Sentry on the server in `connectors.sentry`.\n- Supported delivery modes are `auto` and `manual`.\n- If Sentry is already initialized by the application, Blyp reuses the existing client.\n- Browser and Expo Sentry requests still go through Blyp ingestion first.\n\n## Required implementation steps\n\n1. Add or update `connectors.sentry` in `blyp.config.*`.\n2. Set `enabled: true` and choose `mode: \"auto\"` or `mode: \"manual\"`.\n3. Provide `dsn` and optional `environment` or `release`.\n4. If manual control is required, import from `@blyp/core/sentry`.\n5. If browser or Expo code requests `connector: \"sentry\"`, verify the server connector is configured first.\n\n## Verification checklist\n\n- `connectors.sentry` exists in `blyp.config.*`\n- The connector mode is explicit\n- Existing app-level Sentry initialization is not accidentally replaced\n- Browser or Expo forwarding still targets Blyp ingestion first\n- Manual code imports from `@blyp/core/sentry` when needed\n\n## References\n\n- Config key: `connectors.sentry`\n- Manual import path: `@blyp/core/sentry`\n- Manual APIs: `createSentryLogger()`, `createStructuredSentryLogger()`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-sentry/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-sentry\ndescription: Portable Blyp connector add-on skill for Sentry using connectors.sentry, auto or manual delivery modes, and browser or Expo forwarding requests through Blyp ingestion.\n---\n\n# Blyp Sentry\n\n## What this skill is for\n\nUse this add-on when Blyp logs or structured events should be forwarded into Sentry.\n\n## When to use it\n\n- Configuring `connectors.sentry`\n- Choosing `mode: \"auto\"` or `mode: \"manual\"`\n- Reusing an existing Sentry client in the application\n- Supporting browser or Expo requests that ask Blyp to forward into Sentry\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first.\n- Configure Sentry on the server in `connectors.sentry`.\n- Supported delivery modes are `auto` and `manual`.\n- If Sentry is already initialized by the application, Blyp reuses the existing client.\n- Browser and Expo Sentry requests still go through Blyp ingestion first.\n\n## Required implementation steps\n\n1. Add or update `connectors.sentry` in `blyp.config.*`.\n2. Set `enabled: true` and choose `mode: \"auto\"` or `mode: \"manual\"`.\n3. Provide `dsn` and optional `environment` or `release`.\n4. If manual control is required, import from `@blyp/core/sentry`.\n5. If browser or Expo code requests `connector: \"sentry\"`, verify the server connector is configured first.\n\n## Verification checklist\n\n- `connectors.sentry` exists in `blyp.config.*`\n- The connector mode is explicit\n- Existing app-level Sentry initialization is not accidentally replaced\n- Browser or Expo forwarding still targets Blyp ingestion first\n- Manual code imports from `@blyp/core/sentry` when needed\n\n## References\n\n- Config key: `connectors.sentry`\n- Manual import path: `@blyp/core/sentry`\n- Manual APIs: `createSentryLogger()`, `createStructuredSentryLogger()`\n"},"sha256":"25df520225ec0a525e37960a262109df34f32945ae2a83e7531a76cc908ee80f","digest":"sha256:25df520225ec0a525e37960a262109df34f32945ae2a83e7531a76cc908ee80f"}]},{"name":"blyp-workers","type":"skill-md","description":"Portable Blyp add-on skill for Cloudflare Workers using @blyp/core/workers, initWorkersLogger(), createWorkersLogger(), and explicit request emit() calls.","url":"/.well-known/agent-skills/blyp-workers/SKILL.md","digest":"sha256:bc7713b94af407c3042d88fbc6e2b3a177e88d263ddff974bdb0a709c6c21ac3","content":{"text":"---\nname: blyp-workers\ndescription: Portable Blyp add-on skill for Cloudflare Workers using @blyp/core/workers, initWorkersLogger(), createWorkersLogger(), and explicit request emit() calls.\ncompatibility: Requires a Cloudflare Workers-compatible runtime.\n---\n\n# Blyp Workers\n\n## What this skill is for\n\nUse this add-on when the runtime is Cloudflare Workers rather than Node.js or Bun server adapters.\n\n## When to use it\n\n- Initializing Blyp in a Worker\n- Creating request-scoped Worker loggers\n- Emitting request or error records manually\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first, but override its Node/Bun assumptions with Workers rules.\n- Import from `@blyp/core/workers`.\n- Use `initWorkersLogger()` for shared worker-level setup.\n- Use `createWorkersLogger(request)` per request.\n- Workers do not use `blyp.config.*`.\n- Workers do not support file logging.\n- Workers do not auto-register client ingestion.\n- Request records are emitted manually through `emit()`.\n\n## Required implementation steps\n\n1. Import `initWorkersLogger` and `createWorkersLogger` from `@blyp/core/workers`.\n2. Initialize the worker logger once during startup.\n3. Create a request logger inside the `fetch` handler.\n4. Set request-scoped fields with `log.set(...)` as needed.\n5. Call `log.emit({ response })` on success and `log.emit({ error })` on failure.\n6. Do not add Node-oriented config files or file logging settings to Workers code.\n\n## Verification checklist\n\n- The worker imports from `@blyp/core/workers`\n- `initWorkersLogger()` runs once\n- `createWorkersLogger(request)` is used per request\n- `emit()` is called explicitly\n- No `blyp.config.*` or file logging assumptions leak into the Worker implementation\n\n## References\n\n- Import path: `@blyp/core/workers`\n- Main APIs: `initWorkersLogger()`, `createWorkersLogger()`\n- Request emission: `emit()`\n"},"sha256":"bc7713b94af407c3042d88fbc6e2b3a177e88d263ddff974bdb0a709c6c21ac3","skillDocument":"---\nname: blyp-workers\ndescription: Portable Blyp add-on skill for Cloudflare Workers using @blyp/core/workers, initWorkersLogger(), createWorkersLogger(), and explicit request emit() calls.\ncompatibility: Requires a Cloudflare Workers-compatible runtime.\n---\n\n# Blyp Workers\n\n## What this skill is for\n\nUse this add-on when the runtime is Cloudflare Workers rather than Node.js or Bun server adapters.\n\n## When to use it\n\n- Initializing Blyp in a Worker\n- Creating request-scoped Worker loggers\n- Emitting request or error records manually\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first, but override its Node/Bun assumptions with Workers rules.\n- Import from `@blyp/core/workers`.\n- Use `initWorkersLogger()` for shared worker-level setup.\n- Use `createWorkersLogger(request)` per request.\n- Workers do not use `blyp.config.*`.\n- Workers do not support file logging.\n- Workers do not auto-register client ingestion.\n- Request records are emitted manually through `emit()`.\n\n## Required implementation steps\n\n1. Import `initWorkersLogger` and `createWorkersLogger` from `@blyp/core/workers`.\n2. Initialize the worker logger once during startup.\n3. Create a request logger inside the `fetch` handler.\n4. Set request-scoped fields with `log.set(...)` as needed.\n5. Call `log.emit({ response })` on success and `log.emit({ error })` on failure.\n6. Do not add Node-oriented config files or file logging settings to Workers code.\n\n## Verification checklist\n\n- The worker imports from `@blyp/core/workers`\n- `initWorkersLogger()` runs once\n- `createWorkersLogger(request)` is used per request\n- `emit()` is called explicitly\n- No `blyp.config.*` or file logging assumptions leak into the Worker implementation\n\n## References\n\n- Import path: `@blyp/core/workers`\n- Main APIs: `initWorkersLogger()`, `createWorkersLogger()`\n- Request emission: `emit()`\n","files":[{"path":"SKILL.md","url":"/.well-known/agent-skills/blyp-workers/SKILL.md","mediaType":"text/markdown","content":{"text":"---\nname: blyp-workers\ndescription: Portable Blyp add-on skill for Cloudflare Workers using @blyp/core/workers, initWorkersLogger(), createWorkersLogger(), and explicit request emit() calls.\ncompatibility: Requires a Cloudflare Workers-compatible runtime.\n---\n\n# Blyp Workers\n\n## What this skill is for\n\nUse this add-on when the runtime is Cloudflare Workers rather than Node.js or Bun server adapters.\n\n## When to use it\n\n- Initializing Blyp in a Worker\n- Creating request-scoped Worker loggers\n- Emitting request or error records manually\n\n## Blyp-specific rules and constraints\n\n- Install `blyp-core` first, but override its Node/Bun assumptions with Workers rules.\n- Import from `@blyp/core/workers`.\n- Use `initWorkersLogger()` for shared worker-level setup.\n- Use `createWorkersLogger(request)` per request.\n- Workers do not use `blyp.config.*`.\n- Workers do not support file logging.\n- Workers do not auto-register client ingestion.\n- Request records are emitted manually through `emit()`.\n\n## Required implementation steps\n\n1. Import `initWorkersLogger` and `createWorkersLogger` from `@blyp/core/workers`.\n2. Initialize the worker logger once during startup.\n3. Create a request logger inside the `fetch` handler.\n4. Set request-scoped fields with `log.set(...)` as needed.\n5. Call `log.emit({ response })` on success and `log.emit({ error })` on failure.\n6. Do not add Node-oriented config files or file logging settings to Workers code.\n\n## Verification checklist\n\n- The worker imports from `@blyp/core/workers`\n- `initWorkersLogger()` runs once\n- `createWorkersLogger(request)` is used per request\n- `emit()` is called explicitly\n- No `blyp.config.*` or file logging assumptions leak into the Worker implementation\n\n## References\n\n- Import path: `@blyp/core/workers`\n- Main APIs: `initWorkersLogger()`, `createWorkersLogger()`\n- Request emission: `emit()`\n"},"sha256":"bc7713b94af407c3042d88fbc6e2b3a177e88d263ddff974bdb0a709c6c21ac3","digest":"sha256:bc7713b94af407c3042d88fbc6e2b3a177e88d263ddff974bdb0a709c6c21ac3"}]}];
function decodeBase64(value) {
  const binary = globalThis.atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}
function hydrateContent(content) {
  return typeof content.text === "string" ? content.text : decodeBase64(content.base64);
}
export const bundledAgentSkills = snapshot.map((skill) => ({
  ...skill,
  content: hydrateContent(skill.content),
  files: skill.files.map((file) => ({ ...file, content: hydrateContent(file.content) })),
}));
